INSERT INTO `dr_1_cases_data_0` (`id`, `uid`, `catid`, `content`, `banner`, `content_1`, `content_2`, `content_3`, `content_4`, `content_6`, `content_7`) VALUES ('37','1','2','','{"1":{"1":"/images/solution.jpg","2":"/images/solutionm.jpg"}}','{"1":{"1":"行业需求","2":"在低空威胁持续升级的背景下，电网变电站、石油生产等关键基础设施频繁遭受“黑飞”无人机侵扰，构建高效低空防御屏障已成为行业刚需。通过将光电转台与反无人机设备深度融合，搭建一体化协同防御体系，以光电转台为核心感知单元，搭载双波段探测技术，可全天候精准捕捉无人机轨迹、识别目标并同步传输数据，有效解决传统防御痛点，为精准反制提供坚实支撑。\\r\\n反无人机设备依托前端感知数据，采用无线电监测与导航诱骗相结合的模式，可灵活采用固定与移动部署方式，同时通过参数优化避免对关键设施设备产生干扰，实现变电站等重点区域外围察打一体。系统协同实现全流程自动化运行，能够适配全天候复杂场景，高效抵御各类低空非法无人机威胁，切实守护关键设施安全，助力行业平稳有序发展。","3":"142"}}','方案概述','{"1":{"1":"化工企业厂区","2":"化工企业厂区属于高风险区域，遍布易燃易爆设施，低空安防核心是实现无人机的预警与精准处置，严防无人机侵入引发安全或窃密事故。系统以防爆为首要原则，在核心区域划定电子围栏、部署智能光电转台，借助红外热成像实现24小时监测。通过AI算法识别无人机后，立即发出最高级别告警并追踪轨迹，优先采用导航欺骗、定向压制等安全反制方式，保障厂区安全。"},"2":{"1":"石油生产基地","2":"石油生产基地低空安防中，光电转台部署于厂区高耸设施顶端，选用超远距型号，实现生产区、储油罐区及周边区域的无缝全覆盖监控，保障大范围安防监测需求。反无设备采用分层应用策略，外围部署无线电侦测设备定位无人机操控者，预警区启用导航欺骗驱离无人机，核心区域则用定向干扰设备实施迫降，与光电转台协同，实现监控与反制联动，全方位防范安全风险。"},"3":{"1":"水利发电大坝","2":"水利发电大坝是国家关键基础设施，低空安防聚焦大坝本体、发电厂房等重点区域，应对地形复杂、干扰物多的问题。系统依地形部署光电转台，利用热成像克服水面反光、雾气影响，通过AI算法过滤飞鸟干扰。发现可疑无人机后立即启动大功率干扰，强制迫降，同时与调度中心互通，不影响发电站正常运行。"}}','{"1":{"1":"机场反无应用","2":"145"},"2":{"1":"发电设施反无应用","2":"144"},"3":{"1":"天然气设施反无应用","2":"143"}}','["6","7","8"]','48,59,57,64');
INSERT INTO `dr_1_cases_data_0` (`id`, `uid`, `catid`, `content`, `banner`, `content_1`, `content_2`, `content_3`, `content_4`, `content_6`, `content_7`) VALUES ('38','1','2','','{"1":{"1":"32","2":"32"}}','{"1":{"1":"行业需求","2":"关键要地是保障社会稳定、经济有序运行与公共安全的核心载体，对维持地区正常运转、保障对外联系畅通具有不可替代的作用。此类区域普遍具有管控范围广、人员流动大等特点，易面临违规无人机闯入引发的信息泄露、设施损毁等安全隐患，对安防技术与装备的精度、可靠性均提出了更高要求。\\r\\n关键要地安全防护以全方位、智能化立体防控为核心，整合光电监控、反制无人机、智能安检三大核心板块。光电监控依托多光谱成像、激光测距等技术，实现全域全天候精准监测与目标定位；反无人机设备可有效阻断违规无人机信号，防范低空安全风险；安检设备采用智能检测技术，实现人员与物品的快速精准查验，从而筑牢关键要地安全防线，保障其安全稳定运行。","3":"138"}}','方案概述','{"1":{"1":"司法部门安全防护","2":"司法部门是维护社会公平正义的核心机构，其场所人员流动频繁、涉密信息集中，面临无人机闯入、设施损坏等隐患，对安防要求极高。司法部门安全防护以全方位、智能化防控为核心，统筹部署光电监控、反无设备、安检设备三大板块，实现全域全天候监测、阻断违规无人机信号、精准查验人货，筑牢安全防线，保障各项工作稳定开展。"},"2":{"1":"大型体育赛事安全防护","2":"大型体育赛事是展现城市形象的重要载体，参与人员密集、规模庞大、社会关注度高，面临无人机闯入、人员拥挤、违禁物品带入等风险，对安防精准性、高效性要求严格。其安全防护以全方位、智能化防控为核心，融合光电监控、反无设备、安检设备三大核心装备，实现场馆全域全天候监测、防范低空风险、高效拦截违禁物品，破解防控难题，守护赛事安全有序举办。"},"3":{"1":"机场安全防护","2":"机场是人员物资流通的重要枢纽，人员流动频繁、区域广阔、场景复杂，面临无人机闯入、违禁物品带入、人员异常流动等风险，对安防要求极高。机场安全防护以全方位、智能化防控为核心，整合运用光电监控、反无设备、安检设备三大核心设施，实现航站楼、跑道等区域全域监测，阻断无人机信号、精准查验人货，守护机场运行及旅客出行安全。"}}','{"1":{"1":"要地安保","2":"139"},"2":{"1":"赛事保障","2":"140"},"3":{"1":"交通枢纽安保","2":"141"}}','["6","7","8"]','48,64,88,95,90,87');
INSERT INTO `dr_1_cases_data_0` (`id`, `uid`, `catid`, `content`, `banner`, `content_1`, `content_2`, `content_3`, `content_4`, `content_6`, `content_7`) VALUES ('39','1','2','','{"1":{"1":"33","2":"33"}}','{"1":{"1":"行业需求","2":"边海防是关系国家安全与发展全局。传统海防一线任务繁重，反渗透、反走私等防控压力突出，智慧边海防空地一体建设为提升防控效能带来重要机遇。\\r\\n无人机搭载高性能光电吊舱，可开展大范围海域巡检，实现全域动态监测；智能光电转台作为边海防监控设备，具备可见光与红外热成像双光谱系统，能7×24小时无死角监控，精准捕捉目标细节，夜晚环境定位可疑目标。其融入AI算法与高精度控制技术，可锁定追踪移动目标、过滤干扰，实现“识别-追踪-预警”智能化。二者协同联动，同步传输高清画面，为指挥决策提供精准支撑，成为守护海上安全、打击违法活动的利器，助力构建全方位、立体化的智能化边海防防控体系。","3":"134"}}','方案概述','{"2":{"1":"无人机海防巡逻","2":"海防日常巡逻可精准满足警用定点范围内的精细巡检需求，有效替代或协助现有警用装备与执勤人员开展常态化巡防任务，大幅减轻一线值守压力。通过搭载双光红外吊舱等设备，可实现全天候、远距离实时监控，画面与数据同步回传指挥平台。同时支持远程下达任务指令，依托高空喊话器开展警示劝导、法律宣传、现场驱离等执法操作，提升海防巡逻管控的智能化水平与应急处置能力。"},"3":{"1":"陆基海域监控预警","2":"当前海防监管与应急处置能力薄弱，存在监控手段单一、感知不全、视频质量差，缺乏智能联动与事前预警，数据整合共享不足，应急响应及现场管控支撑手段欠缺等问题，海上各类非法活动威胁日趋严峻。为此需构建陆基海域监控预警系统，融合雷达、光电等多源信息，运用智能分析与联动跟踪技术，建成数字化、智能化海防管控体系，实现全天候监控、自动预警与高效处置，提升边海防综合管控能力。"},"4":{"1":"无人机海防应急救援","2":"海防应急救援在海上突发险情、事故及各类应急事件时，无人机可快速响应、第一时间飞抵事发海域，实时回传现场全景画面与态势信息，为后方指挥中心提供直观研判依据，实现高效辅助决策与远程调度。同时可开展现场警戒、目标搜寻、人员定位等工作，必要时搭载应急投放装置，精准投递救生衣、救生圈、急救包等救生物资，为遇险人员争取宝贵救援时间，显著提升海上应急救援效率与处置能力。"}}','{"1":{"1":"非法船只监管","2":"136"},"2":{"1":"海岸线24小时监测","2":"135"},"3":{"1":"边境地区常态巡逻","2":"137"}}','["6","7","8"]','45,42,25');
INSERT INTO `dr_1_cases_data_0` (`id`, `uid`, `catid`, `content`, `banner`, `content_1`, `content_2`, `content_3`, `content_4`, `content_6`, `content_7`) VALUES ('40','1','2','','{"1":{"1":"34","2":"34"}}','{"1":{"1":"行业需求","2":"为持续提升防灾减灾救灾综合能力、强化风险前置防控、高效处置各类自然灾害，应急管理部紧扣统一领导、权责一致、权威高效的国家应急能力体系建设要求，加快推进应急管理体系和能力现代化，着力构建大安全、大应急工作格局。\\r\\n在自然灾害综合防治与应急处置领域，应急管理部加快落地应急管理大数据工程及自然灾害监测预警信息化工程本级项目建设；同时推动各级应急管理部门深化与自然资源、水利、气象等行业部门协同联动，打通监测预警数据壁垒，实现信息互联互通、共享共用，已初步建成覆盖全域的自然灾害综合监测预警体系。","3":"130"}}','方案概述','{"1":{"1":"应急通信无人机","2":"应急通信无人机搭载一体化高空基站，依托卫星中继链路实现远距离数据回传，可快速在灾害损毁区域重建 4G/5G 公网覆盖，保障受灾群众语音通话、短信收发与无线网络接入。设备兼容自组网模块，能够即时搭建现场专属应急专网，贯通救援前后方通信信道，实现指挥指令、现场数据的实时双向传输，全面提升应急救援调度与协同指挥效率。"},"2":{"1":"应急侦查无人机","2":"应急侦查无人机机动灵活、部署迅速，可突破道路阻断、山地丛林等复杂地形限制，适配各类突发事件处置场景。机身集成高清光电摄像、红外搜救等多功能载荷，支持大范围巡航探测与实时影像回传，助力指挥中心全景掌握灾情态势、精准定位被困人员、识别风险隐患，为资源调配、救援规划与应急决策提供直观可靠的可视化数据支撑。"},"3":{"1":"应急照明无人机","2":"应急照明无人机配备大功率高亮 LED 照明模组，升空部署便捷，无惧复杂场地与恶劣环境约束，可实现高空大范围、多角度无盲区持续补光。采用系留持续供电模式，支持长时间定点悬停作业，有效解决传统地面照明照射范围小、移动不便、存在照明死角等痛点，广泛应用于夜间搜救、道路抢修、人群疏散等场景，强化夜间应急作业保障能力。"}}','{"1":{"1":"震后应急通讯搭建","2":"133"},"2":{"1":"水灾情况现场监测","2":"132"},"3":{"1":"抢修现场应急照明","2":"131"}}','["6","7","8"]','46,45,24');




