INSERT INTO `dr_1_jobs` (`id`, `catid`, `title`, `thumb`, `keywords`, `description`, `hits`, `uid`, `author`, `status`, `url`, `link_id`, `tableid`, `inputip`, `inputtime`, `updatetime`, `displayorder`, `xingzhi`, `leixing`, `area`, `num`, `company`, `email`, `sqdz`) VALUES ('18','16','海外营销',null,null,'职位描述:                        1.负责产品或区域的市场开发；开发客户资源，寻找潜在客户；                        2.根据市场营销计划，完成总部分配的销售任务；                        3.从销售和客户需求的角度，对产品的研发提供指导性建议；','1','1','创始人','9','/index.php?c=show&id=18','0','0','127.0.0.1-49395','1766162755','1776310600','0','面议','兼职','北京','5','宁芯动力','scarlett.chen@enpower-greentech.com','');



INSERT INTO `dr_1_jobs_data_0` (`id`, `uid`, `catid`, `content`) VALUES ('18','1','16','&lt;div class=&quot;info&quot;&gt;
                        &lt;b&gt;职位描述:&lt;/b&gt;&lt;br&gt;
                        1.负责产品或区域的市场开发；开发客户资源，寻找潜在客户；&lt;br&gt;
                        2.根据市场营销计划，完成总部分配的销售任务；&lt;br&gt;
                        3.从销售和客户需求的角度，对产品的研发提供指导性建议；
                    &lt;/div&gt;
                    &lt;div class=&quot;info&quot;&gt;
                        &lt;b&gt;任职要求：&lt;/b&gt;&lt;br&gt;
                        1.法语，西班牙语，阿拉伯语区营销岗各一人，必须会其中一种语言并达到专业能力，能与国外客户流畅沟通，日常商务文件能翻译。 
 英语听读写熟练。&lt;br&gt;
2.能熟练使用常用办公软件，独立完成报价。&lt;br&gt;
3.够在公司领导下维护和开拓销售市场，协调公司内部资源，做好客户公关，完成销售目标。&lt;br&gt;
4.有至少2-3年或以上的外贸经验，年龄26-45，了解新媒体营销。&lt;br&gt;
5.有军民融合产品海外销售的相关经验者优先。6.月薪(基本工资+补贴+绩效工资)，销售提成，年终奖。&lt;br&gt;
7.国家法定假日休息，工作时间上午10:00-6:00
