INSERT INTO `dr_1_product_data_0` (`id`, `uid`, `catid`, `content`, `images`, `desc`, `banner`, `cases`, `content_2`, `content_3`, `content_4`) VALUES ('51','1','11','&lt;p class=&quot;MsoNormal&quot;&gt;FC-DTVC系列双波段热成像高速球是为特种应用场合设计的光学产品。产品整体采用高速球设计理念，结构简单可靠、紧凑精巧；定位精度高转速快，启停平稳，控制方便。集成高清可见光、激光照明模块、动力机构、精密传动装置、数字解码器、图像处理模块和控制模块等，适用于全天候昼夜24小时的图像采集及监控。&lt;br&gt;&lt;/p&gt;','',null,null,null,'{"1":{"1":"多维感知：支持图像标尺；支持接入多种传感器。"},"2":{"1":"高清可见光、视频编码、云台护罩、控制电子系统于一体，模块化设计、集成度高，易于安装维护。"},"3":{"1":"内置GPU芯片，支持区域入侵、进入/离开区域检测、人员聚集检测、徘徊检测、物品遗留、物品拿取等多种检测算法。"},"4":{"1":"支持自诊断自恢复，支持强光保护、防太阳灼伤，支持多组态场景模式，大幅提升使用体验、降低使用成本。"},"5":{"1":"可扩展激光测距、北斗/GPS等传感器，组成多功能态势感知的远距离监测设备。"}}','&lt;table&gt;
