INSERT INTO `dr_1_product_data_0` (`id`, `uid`, `catid`, `content`, `images`, `desc`, `banner`, `cases`, `content_2`, `content_3`, `content_4`) VALUES ('59','1','7','&lt;p class=&quot;MsoNormal&quot;&gt;便携式无人机察打一体设备集侦测、跟踪、定位、反制、联网功能于一体，单设备即可实现无人机管控全流程工作；系统续航充足、重量轻、加固设计，非常适合背负/手持。&lt;o&gt;&lt;/o&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot;&gt;设备通过无线电频率扫描无人机频谱特征、报文协议解析，侦测非法入侵的无人机，能够识别无人机与遥控器之间的控制信号、图传信号；并通过电磁压制技术，实现对无人机遥控链路、图传链路和导航信号的干扰阻断，迫使无人机返航或降落。&lt;span style=&quot;mso-spacerun:\'yes\';font-family:宋体;mso-ascii-font-family:\'Times New Roman\';
mso-hansi-font-family:\'Times New Roman\';mso-bidi-font-family:\'Times New Roman\';font-size:14.0000pt;
mso-font-kerning:1.0000pt;&quot;&gt;&lt;o&gt;&lt;/o&gt;&lt;/span&gt;&lt;/p&gt;','',null,null,null,'{"1":{"1":"察打一体：探测与打击一体化设计，高度集成，单台设备即可完成无人机的探测和打击。"},"2":{"1":"探测机型全：支持复杂电磁环境下消费机、行业类及非标无人机的探测识别，虚警率、漏警率低。"},"3":{"1":"打击距离远：空旷环境下可达3km（典型目标：御3）"},"4":{"1":"定向搜寻：采用无线电无源探测技术，静止条件下即可实现360°全向探测，预警后可切换定向探测确定无人机来向。"},"5":{"1":"精准识别：可精准识别主流品牌无人机机身序列号、型号、位置、速度、高度、航迹及遥控器位置信息。"},"6":{"1":"多种打击效果：具备多个频段无线电干扰能力，使无人机产生返航、迫降、悬停效果。"},"7":{"1":"操作便携：体积小、重量轻、易于携带。"},"8":{"1":"超长续航：可配备大容量可充电电池，续航时间长。"}}','&lt;table&gt;
