INSERT INTO `dr_1_product_data_0` (`id`, `uid`, `catid`, `content`, `images`, `desc`, `banner`, `cases`, `content_2`, `content_3`, `content_4`) VALUES ('61','1','7','&lt;p class=&quot;MsoNormal&quot;&gt;该设备采用卫星导航模拟技术，发射导航诱骗信号，使无人机被驱离或迫降。通过部署导航诱骗设备，可使管控区域外的无人机无法进入，管控区域内的无人机无法起飞。&lt;span style=&quot;mso-spacerun:\'yes\';font-family:宋体;mso-ascii-font-family:\'Times New Roman\';
mso-hansi-font-family:\'Times New Roman\';mso-bidi-font-family:\'Times New Roman\';font-size:14.0000pt;
mso-font-kerning:1.0000pt;&quot;&gt;&lt;o&gt;&lt;/o&gt;&lt;/span&gt;&lt;/p&gt;','',null,null,null,'{"1":{"1":"安全可靠：发射功率低，符合国家标准；防爆设计，可应用在石化、能源领域。"},"2":{"1":"型号核准：具有国家工信部颁发的无线电发射设备型号核准证，符合相关行业的国家标准及要求。"},"3":{"1":"覆盖全面：涵盖GPS、GLONASS、伽利略等导航信号，可应对多模导航无人机。"},"4":{"1":"多种干扰效果：定向驱离、区域拒止、区域禁飞。"},"5":{"1":"多级联动：可与低空探测雷达、无线电侦测设备、无线电干扰设备自动联动。"},"6":{"1":"全天候工作：支持夜晚、雨、雪、大雾等条件下正常工作。"}}','&lt;table&gt;
