INSERT INTO `dr_1_product_data_0` (`id`, `uid`, `catid`, `content`, `images`, `desc`, `banner`, `cases`, `content_2`, `content_3`, `content_4`) VALUES ('64','1','7','&lt;p class=&quot;MsoNormal&quot;&gt;光学识别跟踪设备集高清可见光摄像机、制冷/非制冷热成像仪、激光照明器等多频谱探测模块、自动跟踪、智能分析和精密电子控制于一体，采用小型化隐蔽式结构设计，用于实现对小型无人机目标的探测、定位、跟踪和识别，并可与通信侦测分系统、雷达探测分系统互相引导，实现对空中小型无人机或其他低慢小目标的侦察判证和视频取证。&lt;o&gt;&lt;/o&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot;&gt;高品质设计，外壳选用超强铝合金材质，球面低风阻设计，抗强风、低扰动。采用内外双层“三防”技术和真空充氮密封技术，整机防护等级达到IP66,有效确保设备在野外恶劣环镜中长期稳定运转。&lt;span style=&quot;mso-spacerun:\'yes\';font-family:宋体;mso-ascii-font-family:\'Times New Roman\';
mso-hansi-font-family:\'Times New Roman\';mso-bidi-font-family:\'Times New Roman\';font-size:14.0000pt;
mso-font-kerning:1.0000pt;&quot;&gt;&lt;o&gt;&lt;/o&gt;&lt;/span&gt;&lt;/p&gt;','',null,null,null,'{"1":{"1":"负载能力强：可承载长焦可见光摄像机、大口径热像仪、随动激光照明器，选配激光测距、定位导航、数字罗盘等传感模块，实现超远距离目标观测。"},"2":{"1":"探测频谱宽：可集成高清可见光、制冷/非制冷热成像、激光照明器，多波段探测优势互补，主被动探测相结合，多源数据汇聚融合处理，满足昼夜、全天候环境下的监控需求。"},"3":{"1":"调转速度快：回转速度可达80°/s,加速度可达100°/s，启停迅速，运转流畅，有助于捕获、跟踪快速移动目标。"},"4":{"1":"覆盖范围广：方位回转范围0°~360°，俯仰回转范围-90°~+90°，实现无死角探测、全维度覆盖。"},"5":{"1":"控制精度高：采用精密角度编码器配合高精度闭环伺服控制系统，定位精度可达0.02°，高性能图像处理单元搭配高精度聚焦控制机构，实现精确的自动聚焦。"},"6":{"1":"跟踪性能优：多种先进的目标捕获算法和跟踪算法设计的自动跟踪模块，辅以高精度伺服控制，确保目标在快速飞行及变向过程中的稳定跟踪。"},"7":{"1":"智能化程度高：支持目标入侵检测、移动侦测等异常行为检测，支持目标分类识别，支持热点告警、雷达联动、3D缩放定位等功能，大大提升了系统的无人化、自动化、信息化水平。"},"8":{"1":"多重主动保护：强热源保护，内部温度监控，定向工业除霜器，提升系统的可靠性。"},"9":{"1":"环境适应性强：高强度铝合金材料，内外双层三防技术，IP66保护。"}}','&lt;table&gt;
                                &lt;thead&gt;
                                   &lt;tr&gt;
            &lt;th colspan=&quot;2&quot;&gt;基本参数&lt;/th&gt;
            
        &lt;/tr&gt;
                                &lt;/thead&gt;
                                &lt;tbody&gt;
                                    &lt;tr&gt;
        &lt;td&gt;对0.3m*0.3m无人机目标，作用距离&lt;/td&gt;
        &lt;td&gt;可见光跟踪距离≥4000m,识别距离≥3000m&lt;br&gt;热像跟踪距离≥2000m,识别距离≥800m&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr&gt;
        &lt;td&gt;光谱探测器&lt;/td&gt;
        &lt;td&gt;第五代VOx氧化钒非制冷探测器，分辨率640×512像素，22~230mm,10倍连续光学变焦镜头&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr&gt;
        &lt;td&gt;可见光探测器&lt;/td&gt;
        &lt;td&gt;200万像素高清机芯，12.5~775mm高清电动变镜头，日夜切换彩转黑CMOS&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr&gt;
        &lt;td&gt;智能分析&lt;/td&gt;
        &lt;td&gt;越界入侵，自动跟踪，无人机识别&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr&gt;
        &lt;td&gt;重型转台&lt;/td&gt;
        &lt;td&gt;0.01°高精度定位，方位回转范围0~360°，俯仰回转范围±90°，回转速度80°/s，最小速度0.01°/s&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr&gt;
        &lt;td&gt;IP网络接口&lt;/td&gt;
        &lt;td&gt;支持ONVIF/RTSP/28181协议&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr&gt;
        &lt;td&gt;供电&lt;/td&gt;
        &lt;td&gt;AC220V&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr&gt;
        &lt;td&gt;整机功耗&lt;/td&gt;
        &lt;td&gt;≤500W&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr&gt;
        &lt;td&gt;外形尺寸&lt;/td&gt;
        &lt;td&gt;Φ565mm×H880mm&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr&gt;
        &lt;td&gt;总重量&lt;/td&gt;
        &lt;td&gt;≤105kg&lt;/td&gt;
    &lt;/tr&gt;
                                &lt;/tbody&gt;
                            &lt;/table&gt;','');
INSERT INTO `dr_1_product_data_0` (`id`, `uid`, `catid`, `content`, `images`, `desc`, `banner`, `cases`, `content_2`, `content_3`, `content_4`) VALUES ('65','1','7','&lt;p class=&quot;MsoNormal&quot;&gt;设备可独立监测识别无人机的远程识别广播信号(RemoteID,简称RID)，实时提取并显示无人机的序列号(SN)、型号、位置、速度、高度、起飞点以及飞手位置等多维信息。&lt;o&gt;&lt;/o&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot;&gt;可广泛应用于机场、高铁、电力园区、交通枢纽、重要活动安防、全域低空管控等场景下的目标无人机监管等重要场景，实现对无人机及飞手的探测识别监管。该设备可作为新型基础设施，满足城市空域管理建设需求，助力低空经济蓬勃发展。&lt;span style=&quot;mso-spacerun:\'yes\';font-family:宋体;mso-ascii-font-family:\'Times New Roman\';
mso-hansi-font-family:\'Times New Roman\';mso-bidi-font-family:\'Times New Roman\';font-size:14.0000pt;
mso-font-kerning:1.0000pt;&quot;&gt;&lt;o&gt;&lt;/o&gt;&lt;/span&gt;&lt;/p&gt;','',null,null,null,'{"1":{"1":"目标解析定位：支持接收Remote ID报文，解析无人机ID、位置，飞手位置信息。"},"2":{"1":"多目标探测：探测无人机目标及轨迹数量≥12架次。"},"3":{"1":"多系统组网探测：支持与频谱、雷达等设备组网，并融合探测数据。"},"4":{"1":"多传输方式：支持有线网络、4G/5G等数据传输方式。"},"5":{"1":"多标准模式： 支持《民用无人驾驶航空器系统安全要求》(GB42590-2023)强制技术要求的无人机。支持美国ASTM F3411-22a、欧盟ASD-STAN PrEN 4709-002 标准。"},"6":{"1":"拓展ADS-B：具备对ADS-B报文的接收解析能力，可提供周边空域态势感知监视及碰撞冲突预警。"}}','&lt;table&gt;
                                &lt;thead&gt;
                                   &lt;tr&gt;
            &lt;th colspan=&quot;2&quot;&gt;基本参数&lt;/th&gt;
            
        &lt;/tr&gt;
                                &lt;/thead&gt;
                                &lt;tbody&gt;
                                 &lt;tr&gt;
            &lt;td&gt;工作模式&lt;/td&gt;
            &lt;td&gt;Remote ID（标准）、ADS-B（拓展）&lt;/td&gt;
        &lt;/tr&gt;
        &lt;tr&gt;
            &lt;td&gt;监测半径&lt;/td&gt;
            &lt;td&gt;1~2km(全向)&lt;/td&gt;
        &lt;/tr&gt;
        &lt;tr&gt;
            &lt;td&gt;刷新率&lt;/td&gt;
            &lt;td&gt;2~3S/次&lt;/td&gt;
        &lt;/tr&gt;
        &lt;tr&gt;
            &lt;td&gt;多目标监测&lt;/td&gt;
            &lt;td&gt;无人机及飞手数量≥12架次(同时)&lt;/td&gt;
        &lt;/tr&gt;
        &lt;tr&gt;
            &lt;td&gt;设备尺寸&lt;/td&gt;
            &lt;td&gt;L*W*H： 321mm*231mm*126mm（不带天线）&lt;/td&gt;
        &lt;/tr&gt;
        &lt;tr&gt;
            &lt;td&gt;设备重量&lt;/td&gt;
            &lt;td&gt;4.2kg&lt;/td&gt;
        &lt;/tr&gt;
        &lt;tr&gt;
            &lt;td&gt;防护等级&lt;/td&gt;
            &lt;td&gt;IP65&lt;/td&gt;
        &lt;/tr&gt;
        &lt;tr&gt;
            &lt;td&gt;工作温度&lt;/td&gt;
            &lt;td&gt;-40℃ ~ +70℃&lt;/td&gt;
        &lt;/tr&gt;

                                &lt;/tbody&gt;
                            &lt;/table&gt;','');
INSERT INTO `dr_1_product_data_0` (`id`, `uid`, `catid`, `content`, `images`, `desc`, `banner`, `cases`, `content_2`, `content_3`, `content_4`) VALUES ('66','1','7','&lt;p class=&quot;MsoNormal&quot;&gt;无线电侦测设备能够探测发现400MHz、800MHz、900MHz、1.2GHz、1.4GHz、2.4GHz、5.2GHz、5.8GHz频谱范围内无人机的无线电信号，监测范围为半径2km。设备在开启后，可迅速自动对其进行探测、发现，通过声光报警对无人机的探测结果进行预警。&lt;span style=&quot;mso-spacerun:\'yes\';font-family:宋体;mso-ascii-font-family:\'Times New Roman\';
mso-hansi-font-family:\'Times New Roman\';mso-bidi-font-family:\'Times New Roman\';font-size:14.0000pt;
mso-font-kerning:1.0000pt;&quot;&gt;&lt;o&gt;&lt;/o&gt;&lt;/span&gt;&lt;/p&gt;','',null,null,null,'{"1":{"1":"无源检测：只被动接收不发射任何电磁信号，对环境无影响。"},"2":{"1":"全频段侦测：支持400MHz-6GHz全频段侦测。"},"3":{"1":"侦测机型：支持市场大疆系列无人机、道通、哈博森等主流无人机以及部分跳频穿越机。"},"4":{"1":"目标预警：检测到目标后，可以实现振动告警、声音告警和屏幕光告警。"},"5":{"1":"功率检测：支持全频段扫描功率检测。"}}','&lt;table&gt;
                                &lt;thead&gt;
                                   &lt;tr&gt;
            &lt;th colspan=&quot;2&quot;&gt;基本参数&lt;/th&gt;
            
        &lt;/tr&gt;
                                &lt;/thead&gt;
                                &lt;tbody&gt;
                                &lt;tr&gt;
        &lt;td&gt;频率范围&lt;/td&gt;
        &lt;td&gt;支持400MHz-6GHz自定义扫描，默认400MHz、800MHz、900MHz、1.2GHz、1.4GHz、2.4GHz、5.2GHz、5.8GHz&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr&gt;
        &lt;td&gt;探测距离&lt;/td&gt;
        &lt;td&gt;≤2km&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr&gt;
        &lt;td&gt;探测响应时间&lt;/td&gt;
        &lt;td&gt;≤3s&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr&gt;
        &lt;td&gt;工作原理&lt;/td&gt;
        &lt;td&gt;频谱识别&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr&gt;
        &lt;td&gt;测向方式&lt;/td&gt;
        &lt;td&gt;360°检测、不测向&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr&gt;
        &lt;td&gt;操作方式&lt;/td&gt;
        &lt;td&gt;按键操作，支持调节声音、屏幕背光，查看无人机侦测记录&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr&gt;
        &lt;td&gt;电池&lt;/td&gt;
        &lt;td&gt;电池容量1800mAh、续航时间≤3h&lt;br&gt;电池容量5000mAh、续航时间≤8h支持更换电池&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr&gt;
