INSERT INTO `dr_1_product_data_0` (`id`, `uid`, `catid`, `content`, `images`, `desc`, `banner`, `cases`, `content_2`, `content_3`, `content_4`) VALUES ('95','1','8','&lt;p class=&quot;p&quot; style=&quot;margin: 0pt;&quot;&gt;FC-H智慧手机探测门，采用电磁波信号探测技术，具有排除皮带扣、眼镜、钢笔、文具盒等日常用品进行手机检测的功能，可探测人体是否携带处于开机或者关机状态(含移除电池、移除SIM卡）的手机、笔记本、iPad、相机等电子产品，并能进行位置声光报警，显示报警位置；手机用铜箔包裹5层也可报警可应用于学校、保密场所等重要场景。&lt;span style=&quot;mso-spacerun:\'yes\';font-family:微软雅黑;color:rgb(0,0,0);
font-size:12.0000pt;mso-font-kerning:0.0000pt;&quot;&gt;&lt;o&gt;&lt;/o&gt;&lt;/span&gt;&lt;/p&gt;','',null,null,null,'{"1":{"1":"智慧识别：可自动识别排除日常用品进行手机检测。"},"2":{"1":"linux系统：稳定性强，扩展功能广泛。"},"3":{"1":"宽体门板设计：外壳稳定、坚固、耐用、不变形。"},"4":{"1":"自动校准：设备配有自动校准模式，安装时根据场地自动校准，屏蔽干扰。"},"5":{"1":"信号图形化：探测信号图形化波形展示，设备状态一目了然。"},"6":{"1":"超大屏幕显示：采用29寸前后双屏液晶屏显示，各类信息直观清晰。"},"7":{"1":"USB升级：应用软件可通过USB升级。"},"8":{"1":"多区位报警功能：左右两边各有6个区位，警示手机报警位置。"},"9":{"1":"模块化组件设计：运输、维护方便快捷。"},"10":{"1":"区位显示：产品分成12防区，可疑物能在每个区域准确显示。"},"11":{"1":"统计人数：主界面自动显示更新通过人数和报警人数。"},"12":{"1":"四侧定位灯：门体四侧均带有LED灯，能直观地通过定位灯显示违禁物品所在区域，视角可达360°。"},"13":{"1":"声光报警：具有语音报警、灯条闪光报警功能。"},"14":{"1":"高性能CPU：采用6核芯高性能芯片,主频超过1.8GHz。"},"15":{"1":"遥控操作：使用无线鼠标键盘对参数进行设置，参数可以设密码保护，非授权人员无法进行操作。"},"16":{"1":"安全保护：符合国际安全标准，对心脏起博器佩带者、孕妇、磁性介质等无害。"},"17":{"1":"指示灯调试：具有指示灯手动调试功能，可快速排除故障。"},"18":{"1":"严格执行GB15210-2018《通过式金属探测门通用技术规范》国家标准。"}}','&lt;table&gt;
                                &lt;thead&gt;
