INSERT INTO `dr_1_product_data_0` (`id`, `uid`, `catid`, `content`, `images`, `desc`, `banner`, `cases`, `content_2`, `content_3`, `content_4`) VALUES ('96','1','8','&lt;p class=&quot;MsoNormal&quot;&gt;本款豪华智能摆闸是兼具高端质感、智能体验与可靠安防的通道管理设备，适配各类高端室内外场景，为出入口提供高效严谨的一体化管控方案。产品外观精致，选用优质材质搭配精密工艺，质感出众且契合高端场景格调；核心系统运行稳定低噪，门翼设计兼具美观与实用性，搭配LED灯光提升体验。设备具备多重安全防护与精准感应识别，可有效保障通行安全、杜绝非法入侵，同时支持消防联动、应急放行等功能。&lt;span style=&quot;mso-spacerun:\'yes\';font-family:\'Times New Roman\';mso-fareast-font-family:宋体;
font-size:14.0000pt;mso-font-kerning:1.0000pt;&quot;&gt;&lt;o&gt;&lt;/o&gt;&lt;/span&gt;&lt;/p&gt;','',null,null,null,'','&lt;table&gt;
                                &lt;thead&gt;
                                   &lt;tr&gt;
            &lt;th colspan=&quot;2&quot;&gt;基本参数&lt;/th&gt;
            
        &lt;/tr&gt;
                                &lt;/thead&gt;
                                &lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;材质厚度&lt;/td&gt;
&lt;td&gt;SUS304不锈钢，整机厚度1.5mm&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;闸机尺寸&lt;/td&gt;
&lt;td&gt;14001801000mm&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;通道宽度&lt;/td&gt;
&lt;td&gt;≤110CM&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;工艺标准&lt;/td&gt;
&lt;td&gt;激光切割工艺，外观靓丽，外表面平整清洁，无毛刺、飞边、砂眼、气孔等缺陷，无擦伤、划痕、变形、破损、生锈、腐蚀等损伤，无尖锐凸起、边角或棱角&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;驱动电机&lt;/td&gt;
&lt;td&gt;直流无刷电机&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;机芯类型&lt;/td&gt;
&lt;td&gt;无刷螺旋旋齿防撞驱动机芯&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;机芯运行次数&lt;/td&gt;
&lt;td&gt;MTBF≥800万次&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;门翼材质&lt;/td&gt;
&lt;td&gt;有机玻璃（带LED氛围灯）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;开门速度&lt;/td&gt;
&lt;td&gt;开/关速度至少支持10档可调，开门速度≥0.8s&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;机械特性&lt;/td&gt;
&lt;td&gt;具备机械、电流、电子三重防夹&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;电气安全&lt;/td&gt;
&lt;td&gt;自带漏电保护器&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;声光指示&lt;/td&gt;
&lt;td&gt;LED通道指示和通行指示&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;敞开模式&lt;/td&gt;
&lt;td&gt;支持设置敞开时段&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;消防联动&lt;/td&gt;
&lt;td&gt;具有消防联动接口，消防信号触发时门翼常开，信号恢复时自动复位&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;自检功能&lt;/td&gt;
&lt;td&gt;具备自检测、自诊断、自动报警功能&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;语音功能&lt;/td&gt;
&lt;td&gt;集成语音模块，支持自定义语音播报内容，可设置联动语音提示&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;灯光系统&lt;/td&gt;
&lt;td&gt;LED灯光系统+LED通行指示灯+LED氛围灯系统；前端及顶盖柔光LED通行指示（柔和三色灯状态提示）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;警报功能&lt;/td&gt;
&lt;td&gt;非法闯入、尾随、通行超时等情况发生时进行语音警报&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;设备调整功能&lt;/td&gt;
&lt;td&gt;通过主控板内置小按盘，可编程设备运行状态及多种工作模式&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;防夹功能&lt;/td&gt;
&lt;td&gt;光学传感器、机械、电流三重防夹防护；门翼动作遇阻力自动停止，联动语音、指示灯警示并上传报警事件；光学传感器检测到人员在非安全区域时门翼停止，人员离开后自动复位&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;防尾随防反向功能&lt;/td&gt;
&lt;td&gt;双向防反向闯入和双向防尾随功能（可选关闸或警报处理）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;防冲保护功能&lt;/td&gt;
&lt;td&gt;关门状态时门翼锁死，检测到外力冲撞时联动语音、指示灯警示并上传报警事件；受撞击后快速恢复正常状态，时间＜3.5s&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;自动复位功能&lt;/td&gt;
&lt;td&gt;①强行推开10度自动锁死，延时自动复位；②正常开闸后规定时间内未通行，自动取消通行权限并关闭通道&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;自动解锁功能&lt;/td&gt;
&lt;td&gt;紧急情况断电后摆门可自由推开，符合消防要求&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;防甩手功能&lt;/td&gt;
&lt;td&gt;光学传感器精确区分人员通过与行走甩手遮挡，杜绝误判尾随或关闸&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;潜回关闸功能&lt;/td&gt;
&lt;td&gt;支持单通道反潜回、多通道跨主机反潜回；检测到反潜回报警时，联动语音、指示灯警示并上传报警事件&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;多级减速功能&lt;/td&gt;
&lt;td&gt;摆门开关闸启动到停止过程匀加减速控制，摆臂运行更平稳&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;运转噪音&lt;/td&gt;
&lt;td&gt;机械结构平稳运转时噪音≤ 65dB&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;操作温度范围&lt;/td&gt;
&lt;td&gt;-10°C ~60°C&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;贮藏温度范围&lt;/td&gt;
&lt;td&gt;-20 °C ~60°C&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;工作使用温度&lt;/td&gt;
&lt;td&gt;-25°C ~70°C&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;相对湿度&lt;/td&gt;
&lt;td&gt;5%~90%RH (无结露)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;雷达感应&lt;/td&gt;
&lt;td&gt;支持雷达感应判断通道状态（可提供实用型新型专利证明）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;应急放行功能&lt;/td&gt;
&lt;td&gt;断电或故障后处于无拦挡状态&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;设备警示&lt;/td&gt;
&lt;td&gt;对未收到通行信号有人进入、接收到信号有人进入、逆向进入、开机自检不通过、拦挡部分运行不到位、通行超时等情况警示；警示状态可设置为不接受通行指令&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;防尾随功能（国标要求）&lt;/td&gt;
&lt;td&gt;仅接收到一条通行指令时，对间隔≥100mm的尾随人员进行警示&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;视觉/听觉指示功能&lt;/td&gt;
&lt;td&gt;不同工作状态、操作与结果对应不同视觉/听觉指示；允许通行为绿色，禁止通行、警示为红色；警示听觉指示区别于其他指示&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;通行安全&lt;/td&gt;
&lt;td&gt;室外设备外壳和拦挡部分采用热传导性较差材料/隔热防护措施/降热传导处理工艺；机壳开启有防组件伤人保护措施；拦挡部分运动时检测到通道有人，立即停止或运行至允许通行状态&lt;/td&gt;
&lt;/tr&gt;         
&lt;tr&gt;
&lt;td&gt;工作使用温度&lt;/td&gt;
&lt;td&gt;-25°C ~70°C&lt;/td&gt;
&lt;/tr&gt;   
    &lt;/tbody&gt;
                            &lt;/table&gt;','');
INSERT INTO `dr_1_product_data_0` (`id`, `uid`, `catid`, `content`, `images`, `desc`, `banner`, `cases`, `content_2`, `content_3`, `content_4`) VALUES ('97','1','8','&lt;p class=&quot;MsoNormal&quot;&gt;FC-3000智能铁磁探测系统是一款被动式探测铁磁性物质的设备，拥有世界领先的磁通门检测、DSP数字信号处理等核心技术，通过智能软件算法排除周围环境干扰的限制因素，FC-3000是便携的、安全的、可信任的产品。&lt;span style=&quot;mso-spacerun:\'yes\';font-family:宋体;mso-ascii-font-family:\'Times New Roman\';
mso-hansi-font-family:\'Times New Roman\';mso-bidi-font-family:\'Times New Roman\';font-size:14.0000pt;
mso-font-kerning:1.0000pt;&quot;&gt;&lt;o&gt;&lt;/o&gt;&lt;/span&gt;&lt;/p&gt;','',null,null,null,'{"1":{"1":"检测含磁性的金属和非金属物品。"},"2":{"1":"非接触式无源探测，低功耗，不发射有害电磁波。"},"3":{"1":"实时、可视化智能报警。"},"4":{"1":"灵敏度高，NT级，检测铁磁物品三分区定位。"},"5":{"1":"检测范围宽，0-1.5米以此为半径的360度范围。"},"6":{"1":"通过速率高，＞60人次/每分钟。"},"7":{"1":"隐蔽筛查，可放置在物体、门及墙后，可配合智能手表报警，外形可根据安检场所进行隐蔽设计。"},"8":{"1":"内置大容量锂电池可正常运行＞24小时。"},"9":{"1":"双柱联网模式：分级预警功能。（打火机等蓝灯、手机黄灯、管制类刀具红灯）"}}','&lt;table&gt;
                                &lt;thead&gt;
                                   &lt;tr&gt;
            &lt;th colspan=&quot;2&quot;&gt;基本参数&lt;/th&gt;
            
        &lt;/tr&gt;
                                &lt;/thead&gt;
