INSERT INTO `dr_1_product_data_0` (`id`, `uid`, `catid`, `content`, `images`, `desc`, `banner`, `cases`, `content_2`, `content_3`, `content_4`) VALUES ('100','1','8','&lt;p class=&quot;MsoNormal&quot;&gt;FC-PD500 型是一款小型高灵敏度的 X、γ个人辐射剂量报警仪，采用高速的低功耗嵌入
式微处理器作为数据处理单元，探测器采用的是高灵敏的 GM 计数器。仪器具有响应快，测
量范围宽,应用范围广的特点。可监测 X、γ射线和硬β射线，是一款通用型辐射剂量测量仪。&lt;br&gt;&lt;/p&gt;','',null,null,null,'{"1":{"1":"大面积点阵带背光的 LCD 显示器；"},"2":{"1":"中英文菜单式操作界面，操作非常简单方便；"},"3":{"1":"外壳两侧有防滑凹凸槽，带可拆卸式背夹；"},"4":{"1":"高灵敏的 GM 计数器，可测量环境本底；"},"5":{"1":"可同时显示剂量率值、计数率值、累积剂量值、时 间信息、电池电量、报警模式；"},"6":{"1":"脉冲寻源功能，快速查找，定位放射源位置；"},"7":{"1":"自动切换量程；"},"8":{"1":"自动保存累计剂量，断电可长时间保存；"},"9":{"1":"累计剂量和剂量率报警功能；"},"10":{"1":"声音、振动、声音+振动、静音报警方式任意选择；"},"11":{"1":"内置大容量可充电锂电池，电池电压状态实时指示；"},"12":{"1":"自动故障检测及保护功能；"},"13":{"1":"可连续保存 98000 条实时记录和 32000 条报警记 录，数值可通过 USB 导出（需选配专用软件）；"},"14":{"1":"可选配蓝牙通信和手机 APP。"}}','&lt;table&gt;
                                &lt;thead&gt;
                                   &lt;tr&gt;
            &lt;th colspan=&quot;2&quot;&gt;基本参数&lt;/th&gt;
            
        &lt;/tr&gt;
                                &lt;/thead&gt;
                                &lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;测量范围&lt;/td&gt;
&lt;td&gt;剂量率：0.01μSv/h~5000μSv/h；累积剂量：0.00μSv ~9999Sv&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;X、γ能量范围&lt;/td&gt;
&lt;td&gt;30Kev~3.0Mev&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;能量响应误差&lt;/td&gt;
&lt;td&gt;不超过±25%(相对于137Cs)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;相对基本误差&lt;/td&gt;
&lt;td&gt;不超过±15% (在10μSv/h 时，137Cs)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;剂量率报警阈值&lt;/td&gt;
&lt;td&gt;具有两级报警阈值，全量程内可调&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;累计剂量报警阈值&lt;/td&gt;
&lt;td&gt;全量程内可调&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;防护报警响应时间&lt;/td&gt;
&lt;td&gt;≤5 秒(报警阈值为2.5μSv/h)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;显示单位&lt;/td&gt;
&lt;td&gt;剂量率：μSv/h、mSv/h 自动切换；累积剂量：μSv、mSv、Sv 自动切换；计数率：CPS&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;供电方式&lt;/td&gt;
&lt;td&gt;内置3.7V，900mAh 可充电锂电池，Type-C 型充电接口有硅胶防水密封圈&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;外壳尺寸（不含背夹）&lt;/td&gt;
&lt;td&gt;115×60×28(mm)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;重量&lt;/td&gt;
&lt;td&gt;约125g&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;防护等级&lt;/td&gt;
&lt;td&gt;IP65&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;使用环境&lt;/td&gt;
&lt;td&gt;温度-10℃~+50℃，相对湿度≤95% (40±2)℃&lt;/td&gt;
&lt;/tr&gt;              &lt;/tbody&gt;
                            &lt;/table&gt;','');
INSERT INTO `dr_1_product_data_0` (`id`, `uid`, `catid`, `content`, `images`, `desc`, `banner`, `cases`, `content_2`, `content_3`, `content_4`) VALUES ('101','1','9','&lt;p class=&quot;MsoNormal&quot;&gt;装配式人行贝雷桥是一款基于经典贝雷片结构优化设计的模块化钢桥系统，专为满足现代城市建设、景区开发及应急抢险中的人行通行需求而打造。该产品采用高强度钢材预制构件，通过销轴连接实现快速拼装，具备结构轻盈、承载力强、跨度适应性广等特点。无论是跨越河流、公路还是峡谷，其灵活的结构形式都能在极短的工期内完成架设。&lt;o&gt;&lt;/o&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot;&gt;除了卓越的工程性能，人行贝雷桥还兼顾了美观与耐用性。桥体经过专业的防腐处理，能够适应各种恶劣气候环境，维护成本低廉，使用寿命长。&lt;span style=&quot;mso-spacerun:\'yes\';font-family:宋体;mso-ascii-font-family:\'Times New Roman\';
mso-hansi-font-family:\'Times New Roman\';mso-bidi-font-family:\'Times New Roman\';font-size:14.0000pt;
mso-font-kerning:1.0000pt;&quot;&gt;&lt;o&gt;&lt;/o&gt;&lt;/span&gt;&lt;/p&gt;','',null,null,null,'','&lt;table&gt;
                                &lt;thead&gt;
                                   &lt;tr&gt;
            &lt;th colspan=&quot;2&quot;&gt;产品属性&lt;/th&gt;
            
        &lt;/tr&gt;
                                &lt;/thead&gt;
                                &lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;品名&lt;/td&gt;
&lt;td&gt;装配式人行桥&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;别称&lt;/td&gt;
&lt;td&gt;人行道；钢结构人行桥；城市人行桥；钢便桥；临时便道；临时便桥；贝雷人行桥&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;型号&lt;/td&gt;
&lt;td&gt;321型；200型；GWD型；特制钢架等&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;常用架片型号&lt;/td&gt;
&lt;td&gt;321型贝雷片；200型贝雷片；GWD型贝雷片等&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;钢桥设计最大单跨&lt;/td&gt;
&lt;td&gt;60米左右&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;钢桥标准车道净宽&lt;/td&gt;
&lt;td&gt;1.2米，1.5米，2米或者根据需求定制&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;荷载等级&lt;/td&gt;
&lt;td&gt;人群荷载或者小型车辆通行，一般不超过5吨&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;设计方案&lt;/td&gt;
&lt;td&gt;根据跨径与荷载的不同选择合适的组排&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;钢桥主要材质&lt;/td&gt;
&lt;td&gt;GB Q345B&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;连接销子材质&lt;/td&gt;
&lt;td&gt;30CrMnTi&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;连接螺栓等级&lt;/td&gt;
&lt;td&gt;8.8级高强螺栓；G10.9级高强螺栓&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;表面防腐&lt;/td&gt;
&lt;td&gt;热镀锌；油漆；钢结构重型防腐油漆；沥青漆；桥面板防滑骨料处理等&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;桥梁架设方法&lt;/td&gt;
&lt;td&gt;悬臂推出法；就地拼装法；堆土施工法；吊装法；浮运法等&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;安装需要时间&lt;/td&gt;
&lt;td&gt;桥台等条件具备后3-7个晴天日（根据桥梁长度和现场条件确定）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;安装需要工人&lt;/td&gt;
&lt;td&gt;5-6名（根据现场条件确定）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;安装需要设备&lt;/td&gt;
&lt;td&gt;吊车，卷扬机，千斤顶，手拉葫芦，焊机，发电机等（可根据现场条件调整）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;钢桥特点&lt;/td&gt;
&lt;td&gt;造价低，外形美观，配件轻便，装配迅速，可互换，可拆卸，寿命长&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;通过认证&lt;/td&gt;
&lt;td&gt;ISO，CCIC，BV，SGS，CNAS等&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;执行标准&lt;/td&gt;
&lt;td&gt;JT-T/728-2008&lt;/td&gt;
&lt;/tr&gt;           &lt;/tbody&gt;
                            &lt;/table&gt;','{"1":{"1":"","2":"125"},"2":{"1":"","2":"126"}}');
INSERT INTO `dr_1_product_data_0` (`id`, `uid`, `catid`, `content`, `images`, `desc`, `banner`, `cases`, `content_2`, `content_3`, `content_4`) VALUES ('102','1','9','&lt;p class=&quot;MsoNormal&quot;&gt;321型装配式钢桥，是一款经典的模块化、快速反应制式桥梁系统。该桥梁整体结构精选高强度钢材，通过精密的全焊接工艺制造，兼具优异的结构刚度与韧性。其核心主梁采用可分解的轻型桁架结构，节段之间通过独特的单销连接方式进行固定，这种设计不仅赋予了构件极高的标准化互换性，更大幅降低了结构自重，使得整桥的物流运输与现场拆装极为便捷，即便在缺乏大型起重设备的复杂地形下也能高效作业。作为一种高度成熟的应急交通保障解决方案，321型钢桥具备极强的适应性，可根据实际跨径需求和通载等级，广泛应用于抢险救灾、工程便道等领域。&lt;br&gt;&lt;/p&gt;','',null,null,null,'','&lt;table&gt;
                                &lt;thead&gt;
                                   &lt;tr&gt;
            &lt;th colspan=&quot;2&quot;&gt;基本参数&lt;/th&gt;
            
        &lt;/tr&gt;
                                &lt;/thead&gt;
                                &lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;品名&lt;/td&gt;
&lt;td&gt;321型装配式公路钢桥（贝雷钢桥）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;型号别名&lt;/td&gt;
&lt;td&gt;100型装配式公路钢桥（贝雷钢桥）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;衍生型号&lt;/td&gt;
&lt;td&gt;CB100, Compact-100，英制321型&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;桁架片型号&lt;/td&gt;
&lt;td&gt;321型贝雷片&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;桁架片常规尺寸&lt;/td&gt;
&lt;td&gt;3米×1.4米（孔到孔）；通常也说：3米×1.5米（边到边）&lt;/td&gt;
&lt;/tr&gt;
