INSERT INTO `dr_1_product_recycle` (`id`, `cid`, `uid`, `catid`, `content`, `result`, `inputtime`) VALUES ('1','104','1','9','{"1_product":{"id":"104","catid":"9","title":"200型装配式公路钢桥(贝雷桥)","thumb":"102","keywords":"","description":"","hits":"1","uid":"1","author":"创始人","status":"9","url":"/index.php?c=show&id=104","link_id":"0","tableid":"0","inputip":"127.0.0.1-51277","inputtime":"1774684030","updatetime":"1774684030","displayorder":"0","hot":null,"list_desc":null,"icon":null,"xinghao":"N-TET"},"1_product_data_0":{"id":"104","uid":"1","catid":"9","content":"&lt;p class=&quot;MsoNormal&quot;&gt;200型装配式钢桥从外观上看与&quot;321&quot;型贝雷钢桥相似，但将桁架高度提高到2.134米。对于部分较长跨径的钢桥，可以采取加强弦杆间的接头与桁架间的接头错开布置，减小因销孔间隙引起的非弹性变形，并采用预拱的方法，大大减少桥梁跨中竖向挠度。螺栓连接构件采用导向套定位固定的方法增加了产品连接精度，导向套受剪，螺栓受拉，提高了螺栓的使用寿命，保证了装配式钢桥的安全性。抗风拉杆制作成整体式，并与横梁连接，提高装配式钢桥的整体稳定性。水平支撑架与桁架片之间是跨接固定，这样可保证整桥没有侧弯，整桥架好后并带预拱度。200型装配式钢桥除可组装成单车道桥梁外，还可组装成双车道桥梁，从而扩大了桥梁的使用范围。&lt;span style=&quot;mso-spacerun:\'yes\';font-family:宋体;mso-ascii-font-family:\'Times New Roman\';\\r\\nmso-hansi-font-family:\'Times New Roman\';mso-bidi-font-family:\'Times New Roman\';font-size:14.0000pt;\\r\\nmso-font-kerning:1.0000pt;&quot;&gt;&lt;o&gt;&lt;/o&gt;&lt;/span&gt;&lt;/p&gt;","images":"","desc":null,"banner":null,"cases":null,"content_2":"","content_3":"&lt;table&gt;\\r\\n                                &lt;thead&gt;\\r\\n                                   &lt;tr&gt;\\r\\n            &lt;th colspan=&quot;2&quot;&gt;基本参数&lt;/th&gt;\\r\\n            \\r\\n        &lt;/tr&gt;\\r\\n                                &lt;/thead&gt;\\r\\n                                &lt;tbody&gt;\\r\\n&lt;tr&gt;\\r\\n        &lt;td&gt;操作系统&lt;/td&gt;\\r\\n        &lt;td&gt;LINUX&lt;/td&gt;\\r\\n    &lt;/tr&gt;\\r\\n    &lt;tr&gt;\\r\\n        &lt;td&gt;运输重量&lt;/td&gt;\\r\\n        &lt;td&gt;约90kg&lt;/td&gt;\\r\\n    &lt;/tr&gt;\\r\\n    &lt;tr&gt;\\r\\n        &lt;td&gt;功耗&lt;/td&gt;\\r\\n        &lt;td&gt;&amp;lt;40W&lt;/td&gt;\\r\\n    &lt;/tr&gt;\\r\\n    &lt;tr&gt;\\r\\n        &lt;td&gt;工作温度&lt;/td&gt;\\r\\n        &lt;td&gt;-10℃~40℃&lt;/td&gt;\\r\\n    &lt;/tr&gt;\\r\\n    &lt;tr&gt;\\r\\n        &lt;td&gt;工作湿度&lt;/td&gt;\\r\\n        &lt;td&gt;95%,无冷凝&lt;/td&gt;\\r\\n    &lt;/tr&gt;\\r\\n    &lt;tr&gt;\\r\\n        &lt;td&gt;外接电源&lt;/td&gt;\\r\\n        &lt;td&gt;187V~242V,50/60HZ&lt;/td&gt;\\r\\n    &lt;/tr&gt;\\r\\n    &lt;tr&gt;\\r\\n        &lt;td&gt;工作频率&lt;/td&gt;\\r\\n        &lt;td&gt;根据安装环境自行调节&lt;/td&gt;\\r\\n    &lt;/tr&gt;\\r\\n    &lt;tr&gt;\\r\\n        &lt;td&gt;外形尺寸&lt;/td&gt;\\r\\n        &lt;td&gt;(mm) 不大于2310(高)×820(宽)×710(深)&lt;/td&gt;\\r\\n    &lt;/tr&gt;\\r\\n    &lt;tr&gt;\\r\\n        &lt;td&gt;通道尺寸&lt;/td&gt;\\r\\n        &lt;td&gt;(mm) 不大于2010(高)×710(宽)×608(深)&lt;/td&gt;\\r\\n    &lt;/tr&gt;              &lt;/tbody&gt;\\r\\n                            &lt;/table&gt;","content_4":""},"1_product_category_data":null}','','1774684365');
