INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('50','了解我们','About us','4ed19f0b21b06e2262b18a2b8b0bff49',null,null,null,'1775542168');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('51','     北京非传装备科技有限公司坐落于北京丽泽商务区，是一家专注于无人与反无人系统领域的国家级高新技术企业。公司立足国内、辐射全球，以统筹海内外优质资源与市场为核心抓手，构建非传统领域高效协同的产业桥梁，矢志打造具有国际竞争力的一流跨国科技企业。我们秉持“连接技术与应用、融通国内与国际”的发展使命，为全球客户提供顶尖一体化安全保障服务。    ','Beijing Non-traditional Equipment Technology Co., Ltd. located in Beijing\'s Lize Business District, is a national high-tech enterprise specializing in unmanned and anti-unmanned systems. Based in China and with a global reach, the company focuses on integrating high-quality resources and markets both domestically and internationally to build efficient and collaborative industrial bridges in non-traditional fields. We are committed to becoming a world-class multinational technology company with international competitiveness. Adhering to the development mission of &quot;connecting technology and applications, and integrating domestic and international markets,&quot; we provide top-tier integrated security services to global clients.','290003f7568f80a9dbd6909214c0904c',null,null,null,'1775544408');
