INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('118','11月26日，2025上海国际汽车零配件、维修检测诊断设备及服务用品展览会（以下简称：“上海零部件展”）在国家会展中心（上海）开幕。展会以“创变・融合・可持续发展”为主题，首次启用全部15个展馆，参展','On November 26, the 2025 Shanghai International Auto Parts, Repair, Testing and Diagnostic Equipment and Service Supplies Exhibition (hereinafter referred to as the "Shanghai Parts Exhibition") opened at the National Exhibition and Convention Center (Shanghai). The exhibition, themed "Innovation, Integration, and Sustainable Development," is the first to utilize all 15 exhibition halls.','2f564028c25d8ab6c82187d7b8ee76fc',null,null,null,'1775542259');
