INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('310','这些参数帮助用户根据探测范围、灵敏度和功耗等需求，选择合适的无人机侦测雷达设备。探测距离和探测高度是重要指标，特别是在广域监控时，选择探测范围大的设备尤为重要。','These parameters help users select appropriate drone detection radar equipment based on their needs for detection range, sensitivity, and power consumption. Detection distance and detection altitude are important indicators, especially for wide-area surveillance, where choosing equipment with a large detection range is crucial.','6089c1f808fdb2eed33781201468ee7d',null,null,null,'1775546631');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('311','3. 无人机侦测雷达的应用场景','3. Application Scenarios of UAV Detection Radar','804f56640af474559d474d45cfbd3cfa',null,null,null,'1775546631');
