INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('314','：防止无人机非法进入机场空域，保障飞机起降的安全。','To prevent drones from illegally entering airport airspace and to ensure the safety of aircraft takeoffs and landings.','d8a69933241d95edc771de176cf0cb1e',null,null,null,'1775546631');
