INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('386','箱组式医疗救治系统_野战医疗_产品中心_非传科技','Containerized Medical Treatment System - Field Medicine - Product Center - Feichuan Technology','95e80718e41524ea98ec45d66435ea59',null,null,null,'1776183660');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('387','本产品是国际首创的“箱组式医疗救治系统”，通过高度集成的模块化设计，彻底颠覆了传统野战医院“展开一长串、撤收一大片”的低效模式。该系统具备极强的机动性与实战适应力，仅需20分钟即可在任何复杂地形下快速构建起一座功能完备的大规模野战医院，实现了从“搬家式”部署到“模块式”展开的革命性跨越，确立了快速响应与高效卫勤保障的行业新标杆。','This product is the world\'s first "container-style medical treatment system." Through its highly integrated modular design, it completely overturns the inefficient traditional field hospital model of "deploying a long line and withdrawing in a large area." The system boasts exceptional mobility and combat adaptability, capable of rapidly constructing a fully functional large-scale field hospital in any complex terrain within just 20 minutes. This represents a revolutionary leap from "relocation-style" deployment to "modular" deployment, setting a new industry benchmark for rapid response and efficient medical support.','125cdaed99396cfc1d1c92fdb409d3e6',null,null,null,'1776183660');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('388','
                                        核心突破：国际首创的模块化箱组设计。                                    ','Key breakthrough: A world-first modular container design.','1132b9a09ed3a112379580f7a6bebf15',null,null,null,'1776183660');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('389','
