INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('405','
                                        此款耐摔、耐用、质量较好。9V电池降至7V左右，探测距离不变；                                    ','This model is drop-resistant, durable, and of good quality. Even with a 9V battery voltage reduced to around 7V, the detection range remains unchanged.','94730dd75966f63c71f1b46d5b3a6c15',null,null,null,'1776191515');
