INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('469','
                                        可检测有效距离：距金属容器底部30mm，非金属容器60mm                                    ','Effective detection distance: 30mm from the bottom of metal containers, 60mm from non-metallic containers','3fb1549f37f4ad7816a2c8016f8230d9',null,null,null,'1776193112');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('470','
                                        危险液体显示：指示灯为红色，并伴随蜂鸣器长响                                    ','Hazardous liquid indicator: The indicator light is red, accompanied by a long beeping buzzer.','f07888d58bc461ff1bae8477628021d3',null,null,null,'1776193112');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('471','
