INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('473','
                                        自校验功能：具有自校验功能，自校验时间1.8秒。                                    ','Self-verification function: It has a self-verification function with a self-verification time of 1.8 seconds.','bc3208b98c8a61b34dcf459970e709c9',null,null,null,'1776193112');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('474','
                                        自动计数功能：可自动计算检测物体数。                                    ','Automatic counting function: can automatically count the number of detected objects.','9861a6c80ba1d5c6a2cca04278803725',null,null,null,'1776193112');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('475','
                                        身份验证功能：具有身份验证功能。                                    ','Authentication function: It has authentication function.','20875e6de933e4c4ae97af3261846d5b',null,null,null,'1776193112');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('476','
                                        人机界面检查：设备人机界面提供全中文界面，并且自带光源。设备使用人员可根据工作环境通过键盘调节设备参数。                                    ','Human-Machine Interface Inspection: The equipment\'s human-machine interface provides a fully Chinese interface and has a built-in light source. Users can adjust equipment parameters via the keyboard according to the working environment.','aa795fd7478e8de777d59cd906bb281d',null,null,null,'1776193112');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('477','
                                        检测方式：独家首创的瓶底检测方式。                                    ','Testing method: A unique and pioneering bottle bottom testing method.','9add0907244268e72fb432303ae17cbd',null,null,null,'1776193112');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('478','
                                        可检测液体类别：普通测量模式和强酸强碱模式下仪器能够对93#汽油、盐酸、硫酸、石油醚等32种密封容器中的易燃或易腐蚀危险液体报警。                                    ','Detectable liquid categories: In both normal measurement mode and strong acid/alkali mode, the instrument can alarm for flammable or corrosive hazardous liquids in 32 types of sealed containers, including 93# gasoline, hydrochloric acid, sulfuric acid, and petroleum ether.','2a0bd60b242551353252701d4d74893a',null,null,null,'1776193112');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('479','
                                        检测时间：绝缘容器（塑料、玻璃、陶瓷容器）：1秒导电容器（铝罐、铁罐）：7.6秒                                    ','Detection time: Insulating containers (plastic, glass, ceramic containers): 1 second; Conductive containers (aluminum cans, iron cans): 7.6 seconds','86640deda22f238809c7a71a89aa10dc',null,null,null,'1776193112');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('480','
                                        报警方式：声/光报警/液晶图文显示，单独关闭报警声音。                                    ','Alarm methods: audible/visual alarm/LCD graphic display; alarm sound can be turned off separately.','9a887476bf5ae6317e1773225d110e7e',null,null,null,'1776193112');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('481','
                                        报警复位：设备在发生报警后能够手动或自动复位，以便进行下一次检测。                                    ','Alarm Reset: The device can be manually or automatically reset after an alarm occurs so that it can be tested again.','bbe7e2123eab48ce8d304c2cb149b151',null,null,null,'1776193112');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('482','
                                        数据存储检查：液体检测结果存储及检索功能，存储量10000次检测，并能够用标准网络接口或USB等接口将数据导出，可以通过PC机上位软件读取和分析。                                    ','Data storage and inspection: Liquid test result storage and retrieval function, with a storage capacity of 10,000 tests, and the ability to export data via standard network interface or USB interface, which can be read and analyzed by PC host software.','33b7361fdb904a7c56fad13ecc69ba2e',null,null,null,'1776193112');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('483','
                                        采用技术：超宽带脉冲微波反射法及热导法                                    ','Technologies employed: Ultra-wideband pulsed microwave reflection method and thermal conductivity method','ab00446901dcd42733b84f86db30101c',null,null,null,'1776193112');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('484','
                                        快速分析：非金属材质瓶液体检测时间不到1秒，金属材质瓶液体检测时间小于4秒。目前行业检测速度最快的液体检测仪，完全适应人流量高峰期的快速安全检查。                                    ','Rapid analysis: Liquid detection time is less than 1 second for non-metallic bottles and less than 4 seconds for metallic bottles. Currently the industry\'s fastest liquid detector, perfectly suited for rapid security checks during peak traffic periods.','915a8f8e437f5cca456f1ff389740aee',null,null,null,'1776193112');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('485','
                                        瓶底检测：全球独创瓶底检测技术，唯一通过容器底部检测的仪器，被测容器内无需留有很多液体即可检测。                                    ','Bottle bottom detection: A globally unique bottle bottom detection technology, the only instrument that detects through the bottom of a container, requiring no large amount of liquid to remain in the container.','3065dc0f96cf43e7a671237bc806077e',null,null,null,'1776193112');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('486','
                                        硫酸报警：全球唯一硫酸检测，行业中唯一能够检测到硫酸的液体检测器，即使是稀硫酸也可以百分百准确测试出来。                                    ','Sulfuric acid alarm: The world\'s only sulfuric acid detector, the only liquid detector in the industry capable of detecting sulfuric acid, even dilute sulfuric acid can be detected with 100% accuracy.','474ecfda4e803f54613b6ae28eb1a2ee',null,null,null,'1776193112');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('487','
                                        环保设计：采用绿色环保设计，采用超宽带脉冲微波反射法及热导法，不含辐射，对人体，被检物品无害，检测方法环保、安全。                                    ','Environmentally friendly design: It adopts a green and environmentally friendly design, using ultra-wideband pulse microwave reflection method and thermal conductivity method. It is radiation-free, harmless to the human body and the tested items, and the testing method is environmentally friendly and safe.','6acc043300aa56a0703dd657352d3cd2',null,null,null,'1776193112');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('488','
                                        报警方式：检测结果通过指示灯报警、声音报警两种模式，同时液晶显示结果，直观便于区别。                                    ','Alarm methods: The detection results are displayed via two modes: indicator light alarm and sound alarm. The results are also displayed on the LCD screen, making them intuitive and easy to distinguish.','fee2c0a5c4be03b58bbfe131e7f3229a',null,null,null,'1776193112');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('489','
                                        存储功能：储存不少于100000次检测，并能通过标准USB接口将数据导出，通过PC机上位软件读取和分析。                                    ','Storage function: Stores no less than 100,000 tests and can export data via a standard USB interface for reading and analysis via PC software.','b56022b18aee43d674e8108cb86e3f66',null,null,null,'1776193112');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('490','
                                        服务保障：24小时售后电话随时为客户提供技术支持，150人服务团队分布全国各地，提供安装，维护和检修。                                    ','Service Guarantee: 24-hour after-sales hotline provides technical support to customers at any time, and a service team of 150 people is located throughout the country to provide installation, maintenance and repair services.','9cf19a6c80ab8e662ded848614ecd070',null,null,null,'1776193112');
