INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('503','X、γ辐射剂量报警仪 FC902_智慧警务_产品中心_非传科技','FC902 X-ray and gamma radiation dose alarm device - Smart Policing - Product Center - Feichuan Technology','21f2a2353de3bc6ce13528b1980406c2',null,null,null,'1776193152');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('504','FC902 系列是一款小型笔式的高灵敏度的 Xγ辐射剂量报警仪，本仪器采用高速的低功耗嵌入式微
处理器作为数据处理单元，探测器模块采用了高灵敏度的闪烁体探测器。仪器具有响应快，测量范围宽，应用范围广的特点，可监测 X、γ射线，是一款通用型便携式辐射测量仪。','The FC902 series is a compact, pen-style, high-sensitivity X-ray and gamma-ray radiation dosimeter. This instrument uses a high-speed, low-power embedded microprocessor as its data processing unit, and its detector module employs a high-sensitivity scintillator detector. The instrument features fast response, a wide measurement range, and broad application, capable of monitoring X-rays and gamma rays; it is a general-purpose portable radiation measuring instrument.','485b4522e823250ca2d905e87bc78d88',null,null,null,'1776193152');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('505','
                                        高灵敏的 CsI 碘化铯闪烁体+ SiPM 固态光电倍增器                                    ','Highly sensitive CsI scintillator + SiPM solid-state photomultiplier','f9bc2004d771b08f52fb1637802c1333',null,null,null,'1776193152');
