INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('507','
                                        小巧的笔式设计，方便携带自带背夹，可装挂绳                                    ','The compact pen-style design makes it easy to carry. It also features a built-in clip and can be fitted with a lanyard.','4b967537319dc9ad70c5f2b0ee6a4e02',null,null,null,'1776193152');
