INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('580','具有消防联动接口，消防信号触发时门翼常开，信号恢复时自动复位','It has a fire alarm linkage interface; the door wing remains open when a fire alarm signal is triggered and automatically resets when the signal is restored.','6962af8ab6479470dfae98214b41d53f',null,null,null,'1776193794');
