INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('584','集成语音模块，支持自定义语音播报内容，可设置联动语音提示','Integrated voice module, supports customizable voice broadcast content, and can be set to provide linked voice prompts.','147489c4d8ce851beae5964207823926',null,null,null,'1776193794');
