INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('586','LED灯光系统+LED通行指示灯+LED氛围灯系统；前端及顶盖柔光LED通行指示（柔和三色灯状态提示）','LED lighting system + LED access indicators + LED ambient lighting system; front and top cover soft-light LED access indicators (soft three-color light status indication)','20f3dbe8d90704da8f4b4d92b024a9ce',null,null,null,'1776193794');
