INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('588','非法闯入、尾随、通行超时等情况发生时进行语音警报','Voice alarms will be activated in case of unauthorized entry, tailgating, or exceeding the permitted time.','86a2139d9ddd0158572a4fad40ebb5c7',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('589','设备调整功能','Equipment adjustment function','6b53de8d82858c1d5f865972bfc1bd7e',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('590','通过主控板内置小按盘，可编程设备运行状态及多种工作模式','The device\'s operating status and various working modes can be programmed via a built-in keypad on the main control board.','f04b49e2e7dff1a9ca3c26771a6201f7',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('591','防夹功能','Anti-pinch function','561eee6c8b5f90aec7b243db45b32850',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('592','光学传感器、机械、电流三重防夹防护；门翼动作遇阻力自动停止，联动语音、指示灯警示并上传报警事件；光学传感器检测到人员在非安全区域时门翼停止，人员离开后自动复位','Triple anti-pinch protection via optical sensors, mechanical components, and electrical current; the door wings automatically stop when encountering resistance, triggering voice and indicator light warnings and uploading alarm events; the door wings stop when the optical sensors detect personnel in an unsafe area and automatically reset after the personnel leave.','c83fa91301817dd29fd24edc430f0dbd',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('593','防尾随防反向功能','Anti-tailgating and anti-reverse function','d9074083ed5ad805e5bb1a19b3d4f07d',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('594','双向防反向闯入和双向防尾随功能（可选关闸或警报处理）','Two-way anti-reverse intrusion and two-way anti-tailgating functions (optional gate closure or alarm handling).','3ae6af4cbbbd828fe42bb714cf156a02',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('595','防冲保护功能','Shock protection function','45c090d81839460d268d377760fb914a',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('596','关门状态时门翼锁死，检测到外力冲撞时联动语音、指示灯警示并上传报警事件；受撞击后快速恢复正常状态，时间＜3.5s','When the door is closed, the door wings lock. Upon detecting an external impact, it triggers an audio and indicator light warning and uploads an alarm event. After being impacted, it quickly returns to normal operation within 3.5 seconds.','482b6a3183e242c29ea475bf8bcb021c',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('597','自动复位功能','Automatic reset function','2f7089d05f3a7539215a71b88768ea60',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('598','①强行推开10度自动锁死，延时自动复位；②正常开闸后规定时间内未通行，自动取消通行权限并关闭通道','① If the gate is forcibly opened 10 degrees, it will automatically lock and reset after a delay; ② If no passage is allowed within a specified time after normal opening, the passage permission will be automatically cancelled and the passage will be closed.','14579a49ba5606cd2de2d36e04256394',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('599','自动解锁功能','Automatic unlock function','d29467c1f52a8d400a0e7a640de99f30',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('600','紧急情况断电后摆门可自由推开，符合消防要求','The swing door can be freely opened after a power outage in an emergency, meeting fire safety requirements.','41efe80e2513a5544beb6815e113f5a3',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('601','防甩手功能','Anti-shake function','5005ff51e3f697145b54c68dd112f7aa',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('602','光学传感器精确区分人员通过与行走甩手遮挡，杜绝误判尾随或关闸','Optical sensors accurately distinguish between people passing by and those walking while swinging their arms to block the view, preventing misjudgments such as tailgating or gate closure.','6ea603e5083a16a3a637c4fb6734c787',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('603','潜回关闸功能','Submerged gate closing function','93186bef42218390a6eb42e75826e3fa',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('604','支持单通道反潜回、多通道跨主机反潜回；检测到反潜回报警时，联动语音、指示灯警示并上传报警事件','Supports single-channel and multi-channel cross-host anti-followback; when an anti-followback alarm is detected, it triggers voice and indicator light alerts and uploads the alarm event.','ab24a13dd8224d6b7480b1271b2396df',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('605','多级减速功能','Multi-stage deceleration function','fde822c4781d92f474c81a1af704d52a',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('606','摆门开关闸启动到停止过程匀加减速控制，摆臂运行更平稳','The swing gate\'s start-up and stop process is controlled by uniform acceleration and deceleration, resulting in smoother swing arm operation.','5c68ee528561782ed0e7aa6453efc9ac',null,null,null,'1776193794');
