INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('617','雷达感应','Radar sensing','45d8282f66c2d048500201d328c379c6',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('618','支持雷达感应判断通道状态（可提供实用型新型专利证明）','Supports radar sensing to determine channel status (utility model patent certificate available).','86ab98a18ec582b54b13d9791ec25e3f',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('619','应急放行功能','Emergency release function','e41d5fb23bbca650e9f22652c4273626',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('620','断电或故障后处于无拦挡状态','Unobstructed state after power failure or malfunction','d9586f0ccdc6e909615fb23046a79d1f',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('621','设备警示','Equipment warning','df4f0b8aa2f458bdba5699b7b2cf84d6',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('622','对未收到通行信号有人进入、接收到信号有人进入、逆向进入、开机自检不通过、拦挡部分运行不到位、通行超时等情况警示；警示状态可设置为不接受通行指令','Warnings will be issued for situations such as someone entering without receiving a passage signal, someone entering with a received signal, entering in the wrong direction, failure of self-test upon startup, malfunction of the barrier, and passage timeout. The warning status can be set to not accept passage commands.','a0301f3a9438a091bcca2476624d282b',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('623','防尾随功能（国标要求）','Anti-tailgating function (national standard requirement)','b6866a92beb6ecd586c2894c72d1bf73',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('624','仅接收到一条通行指令时，对间隔≥100mm的尾随人员进行警示','When only one passage instruction is received, issue a warning to any trailing personnel with a distance of ≥100mm.','8f70d3f9ba955e9bfc22f4326d4cd158',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('625','视觉/听觉指示功能','Visual/auditory indication function','8ac9807826d54060b2f5553fb6806386',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('626','不同工作状态、操作与结果对应不同视觉/听觉指示；允许通行为绿色，禁止通行、警示为红色；警示听觉指示区别于其他指示','Different working states, operations, and results correspond to different visual/auditory indicators; green indicates permission to pass, red indicates prohibition or warning; warning auditory indicators are distinguishable from other indicators.','daefa0f57051c22b07c3fe763010ec16',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('627','通行安全','Traffic safety','c132d9ff5b14d663708b1b3c25c9f1a9',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('628','室外设备外壳和拦挡部分采用热传导性较差材料/隔热防护措施/降热传导处理工艺；机壳开启有防组件伤人保护措施；拦挡部分运动时检测到通道有人，立即停止或运行至允许通行状态','The outdoor equipment casing and barrier components are made of materials with poor thermal conductivity, with thermal insulation measures and heat conduction reduction treatment processes; the casing has anti-injury protection measures when it is opened; if the barrier component detects someone in the passage when it is moving, it will immediately stop or move to a state where passage is permitted.','35265207b49915659935dce5eed1a6e1',null,null,null,'1776193794');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('629','便携爆炸物探测仪FC1800B_智慧警务_产品中心_非传科技','Portable Explosive Detector FC1800B - Smart Policing - Product Center - Feichuan Technology','5d0f7d4a0c9a7bc80da6a5c14de46aa0',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('630','便携式爆炸物毒品探测仪是我公司开发的新一代便携式光电离爆炸物和毒品检测仪，该产品采用先进的光电离高分辨离子迁移谱技术，不含放射源，对人体无任何辐射危害。具有检测速度快、检测灵敏度高、功耗低、体积小、质量轻、便于携带、易于维护、使用环境和要求适应性强等特点，能同时准确检测出黑火药以及国际民航组织规定的全部爆炸物和毒品。','Our company\'s portable explosives and drugs detector is a new generation of portable photoionization explosives and drugs detector. This product utilizes advanced photoionization high-resolution ion mobility spectroscopy technology, contains no radioactive source, and poses no radiation hazard to the human body. It features fast detection speed, high detection sensitivity, low power consumption, small size, light weight, portability, ease of maintenance, and strong adaptability to various operating environments and requirements. It can simultaneously and accurately detect black powder as well as all explosives and drugs specified by the International Civil Aviation Organization (ICAO).','e4f23ebd8486cdaa94d964c0eb7acd9d',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('631','
                                        全球首创的不含放射性源真空紫外光电离源，使用安全、方便，能同时准确分析出爆炸物和毒品成分。                                    ','The world\'s first vacuum ultraviolet photoionization source without radioactive sources is safe and convenient to use, and can accurately analyze the components of explosives and drugs simultaneously.','815ae92123152256a7e563570c0a7154',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('632','
                                        全球独有的黑火药纳克级检测性能，能检测包括烟花爆竹、民用土制炸药等危险物品。                                    ','Its globally unique nanogram-level black powder detection capability enables it to detect dangerous items including fireworks, firecrackers, and homemade explosives.','e62656587e2fe7815c3aa6ebb6efbcbd',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('633','
                                        检测分析速度比同类产品更快，2秒内出结果。                                    ','The detection and analysis speed is faster than similar products, with results available within 2 seconds.','d8bfa4241ff521b0e223d1ba5cc6afb4',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('634','
                                        采用正、负双模式，可同时检测爆炸物和毒品。                                    ','Employing both positive and negative modes, it can simultaneously detect explosives and drugs.','0ed040c7940eb4ea85b601ac6442a7c0',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('635','
                                        开放式数据库，样品库信息可随时升级。                                    ','An open database allows for the continuous upgrading of sample library information.','1b2833e88a37ef4c1e7e891c98dcb3c1',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('636','
                                        精准检测：采用高分辨离子迁移谱技术，在实际工作中，无需对准包裹内危险物品，只需用试纸擦拭被检包裹即可检测出是否携带危险品，操作便捷，检测精准；                                    ','Precise detection: Utilizing high-resolution ion mobility spectrometry technology, in practical work, there is no need to aim at the dangerous items inside the package. Simply wipe the package being inspected with a test strip to detect whether it carries dangerous items. The operation is convenient and the detection is accurate.','2ce7abac5f64a7424da3bcb577d7a742',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('637','
                                        一机双模：采用正、负双模式，一台机器能够实现爆炸物和毒品的双检测；                                    ','Dual-mode operation: Employing both positive and negative modes, a single machine can detect both explosives and drugs.','64dc4d4213d3908cdb32519ad6feb95e',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('638','
                                        一键检测：一键式检测，操作简单；                                    ','One-click detection: One-click detection, simple operation;','2731c2d173426ecda42311e6010fb979',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('639','
                                        准确识别：能够精准识别出危险物品的成分种类，可报出被检危险品品名；                                    ','Accurate identification: It can accurately identify the types of components in hazardous materials and can report the name of the hazardous material being inspected;','3ebf4a5a3a4f12230fd33cc365435441',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('640','
                                        极速分析：检测分析速度比同类产品更快，2秒内出结果；                                    ','Ultra-fast analysis: The detection and analysis speed is faster than similar products, with results available within 2 seconds;','f6ba0675b593dc9892db6e81a6d99767',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('641','
                                        自动校准：具有自动校准功能，能够适应外界各种环境变化；                                    ','Automatic calibration: It has an automatic calibration function and can adapt to various changes in the external environment;','35b54b89f9f1af35672cd3d0e4d16bc0',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('642','
                                        自动清洁：具有自清洗功能，在过负荷检测后能快速且方便自行进行清洁；                                    ','Automatic cleaning: It has a self-cleaning function and can quickly and easily clean itself after overload detection;','a09ed5b7145b1f1826144681f337518a',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('643','
                                        自动诊断：具有故障自动诊断功能，并能实时提示发出警告，用户可依据警告判断仪器是否能够正常运行；                                    ','Automatic diagnosis: It has an automatic fault diagnosis function and can issue warnings in real time. Users can judge whether the instrument can operate normally based on the warnings.','fdfd8865d947b551319c42ead33ea653',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('644','
                                        实时更新：开放式数据库，样品库信息可随时升级；                                    ','Real-time updates: Open database, sample library information can be upgraded at any time;','779b13bb37e1ab35b783840705418a35',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('645','
                                        全彩屏幕：配备2.8寸TFT彩色触摸屏。                                    ','Full-color screen: Equipped with a 2.8-inch TFT color touchscreen.','1c3f249784058aeb4612dfa6827dfddd',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('646','
                                        实时存储：具有实时数据存储、检索、导出等功能，存储量不少于80万条；                                    ','Real-time storage: It has functions such as real-time data storage, retrieval, and export, with a storage capacity of no less than 800,000 records;','edde6dc760c1942f394596700d1ad4d9',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('647','
                                        耗材便宜：基于分子筛的干燥剂，价格低廉，更换方便。                                    ','Inexpensive consumables: Molecular sieve-based desiccants are inexpensive and easy to replace.','d5a14449ec5419316ca3ef06315b2325',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('648','
                                        包装坚固：安全箱加内衬，纸箱封装；                                    ','Sturdy packaging: secure case with inner lining, sealed in cardboard box;','ee90c75ae4f331e0df853f15fdb11cfa',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('649','
                                        售后无忧：24小时售后服务电话随时为客户提供技术支持,全国100多个售后服务驻点预约上门，及时为客户的安装、维护与检修提供保障。                                    ','Worry-free after-sales service: 24-hour after-sales service hotline provides technical support to customers at any time, and more than 100 after-sales service points nationwide are available for on-site appointments to ensure timely installation, maintenance and repair for customers.','a65a44b4c046f8a2eabc362b08e96cce',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('650','产品特点','Features','7561f72f177841d0838fd22b1268efe3',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('651','采用技术','Adopting technology','68034cbd0fa70150b4c4ebdd4ffb61ee',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('652','光电离高分辨离子迁移谱，检测下限（灵敏度）为1纳克TNT标准炸药','Photoionization high-resolution ion mobility spectroscopy, with a detection limit (sensitivity) of 1 nanogram of TNT standard explosive.','47356fdb9c1180e7c6d1a2ed2fe2795f',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('653','可检测炸药类别','Detectable explosive categories','ec73c8abaa4474ce3cf405373fcbe00b',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('654','黑火药、硝酸铵、梯恩梯、太安、黑索今、硝化甘油、奥克托金（HMX）、二硝基甲苯（DNT）、特屈儿、六硝基芪、吉纳及各种民用和土制炸药等；可扩展检测类别，添加新样本','Black powder, ammonium nitrate, TNT, acetylene, rhesin, nitroglycerin, octogen (HMX), dinitrotoluene (DNT), tertrol, hexanitrostilbene, gina, and various civilian and homemade explosives; the detection categories can be expanded to include new samples.','9a1664d829e102c27d78eb7ce6a59f3f',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('655','可检测毒品类别','Detectable drug categories','1035f6b4cab6cf7bd777d0fa27e615bf',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('656','盐酸可卡因、盐酸海洛因、四氢大麻酚、甲基苯丙胺（冰毒）、盐酸氯胺酮（K粉）、盐酸吗啡、罂粟碱、摇头丸、杜冷丁等常见毒品；可根据需要添加新样本','Common drugs include cocaine hydrochloride, heroin hydrochloride, tetrahydrocannabinol (THC), methamphetamine (ice), ketamine hydrochloride (K powder), morphine hydrochloride, papaverine, ecstasy, and pethidine; new samples can be added as needed.','12c00f3baf37b16397634acd12649c9f',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('657','取样方式','Sampling method','a495286586541a0b6cb3c59318c59026',null,null,null,'1776193970');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('658','直接空气采样、擦拭取样；痕量颗粒吸附采样、试纸擦拭取样','Direct air sampling and swab sampling; trace particle adsorption sampling and test strip swab sampling','b7aef441dbd2989c1f80cfeb4c449173',null,null,null,'1776193970');
