INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1029','无线电侦测设备通过对无人机辐射的无线电信号实施检测，运用无线电频谱分析技术、AOA测向技术、协议解析等技术，实现对侦测范围内的无人机的识别预警和侦察测向，可识别上报主流无人机序列号、无人机位置、飞手位置等信息。','Radio detection equipment detects the radio signals emitted by drones and uses technologies such as radio spectrum analysis, AOA direction finding, and protocol parsing to identify, warn, and detect drones within the detection range. It can identify and report information such as the serial number of mainstream drones, drone location, and pilot location.','205b2d81f3370647ec6585fbad5e3f76',null,null,null,'1776200531');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1030','
                                        系统具有对无人机无线电信号实施全面的探测、识别、定位跟踪等功能。                                    ','The system has the functions of comprehensive detection, identification, positioning and tracking of UAV radio signals.','7cce54cdf70c3d18ace0833d482afe4c',null,null,null,'1776200531');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1031','
                                        无源侦测：该装备采用无源探测技术，被动接收信号，不主动发射信号，隐蔽性高，无辐射。                                    ','Passive detection: This equipment uses passive detection technology, passively receiving signals without actively emitting signals, making it highly concealed and radiation-free.','b312c013d7bf71ca1c7d62b79e84f48e',null,null,null,'1776200531');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1032','
                                        识别机型多：支持识别大疆、道通等主流消费机，还可识别改装机、穿越机、WIFI机等。                                    ','It can recognize a wide range of models: It supports the recognition of mainstream consumer cameras such as DJI and Autel, as well as modified cameras, racing cameras, and WIFI cameras.','43c960b96a8b5786720370f1d95ed3a7',null,null,null,'1776200531');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1033','
                                        黑白名单：能够对白名单无人机进行添加/删除，可区分友方和非友方无人机。                                    ','Blacklist/Whitelist: Allows adding/removing drones from the whitelist, and can distinguish between friendly and non-friendly drones.','2e8d8fe2c2fb5cc21bd7ef26c81060a1',null,null,null,'1776200531');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1034','
                                        支持组网定位：对主流机型，单台设备即可进行无人机和飞手定位；对于其他机型，支持两台及以上组网定位跟踪。                                    ','Supports network positioning: For mainstream models, a single device can perform drone and pilot positioning; for other models, it supports networking positioning and tracking of two or more devices.','a0b98399fb4487ac8b6359b7136bc2ea',null,null,null,'1776200531');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1035','
                                        适应性强、可靠性高：该装备具有良好的适应性和高可靠性，可在夜间、浓雾及恶劣天气下工作，可持续工作时间为7天*24小时。                                    ','Highly adaptable and reliable: This equipment has excellent adaptability and high reliability. It can work at night, in dense fog and in severe weather, and can work continuously for 7 days * 24 hours.','ca46023943f12572920ac781581cacb9',null,null,null,'1776200531');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1036','
                                        无人值守：具备无人值守功能，启用无需人工干预，能够自动记录探测到主流无人机的时间、机型、方位角、无人机序列号、遥控器经纬度、无人机经纬度、距离和高度等信息。                                    ','Unattended Operation: Equipped with unattended operation capability, it can be activated without human intervention and automatically record information such as the time of detection of mainstream drones, drone model, azimuth angle, drone serial number, remote controller latitude and longitude, drone latitude and longitude, distance and altitude.','a7d85508f4666bfd1249f4ed9dce539a',null,null,null,'1776200531');
