INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1207','
                                        覆盖全面：涵盖GPS、GLONASS、伽利略等导航信号，可应对多模导航无人机。                                    ','Comprehensive coverage: Covers navigation signals such as GPS, GLONASS, and Galileo, and can handle multi-mode navigation drones.','0b64df440fec7a220eb76e7a3ddb81db',null,null,null,'1776204880');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1208','
