INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1258','无人机远程识别信息监测设备_反无设备_产品中心_非传科技','Remote Identification and Monitoring Equipment for Unmanned Aerial Vehicles (UAVs) - Anti-UAV Equipment - Product Center - Feichuan Technology','113b55c1879f4194b3fc22a060ab9b1b',null,null,null,'1776204893');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1259','设备可独立监测识别无人机的远程识别广播信号(RemoteID,简称RID)，实时提取并显示无人机的序列号(SN)、型号、位置、速度、高度、起飞点以及飞手位置等多维信息。','The device can independently monitor and identify the remote identification broadcast signal (RemoteID, or RID) of drones, and extract and display multi-dimensional information such as the drone\'s serial number (SN), model, location, speed, altitude, takeoff point, and pilot\'s position in real time.','1c91a246d796ca8ae3b77b493d97f274',null,null,null,'1776204893');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1260','可广泛应用于机场、高铁、电力园区、交通枢纽、重要活动安防、全域低空管控等场景下的目标无人机监管等重要场景，实现对无人机及飞手的探测识别监管。该设备可作为新型基础设施，满足城市空域管理建设需求，助力低空经济蓬勃发展。','It can be widely used in important scenarios such as airports, high-speed railways, power parks, transportation hubs, security for major events, and comprehensive low-altitude control for target drone monitoring, enabling the detection, identification, and monitoring of drones and pilots. This equipment can serve as a new type of infrastructure, meeting the needs of urban airspace management and construction, and contributing to the vigorous development of the low-altitude economy.','975b2aba51adef78111f7f0559accb33',null,null,null,'1776204893');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1261','
                                        目标解析定位：支持接收Remote ID报文，解析无人机ID、位置，飞手位置信息。                                    ','Target parsing and positioning: Supports receiving Remote ID messages and parsing the drone ID, location, and pilot location information.','f3a33a270aafd767534f8ec6039a61be',null,null,null,'1776204893');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1262','
                                        多目标探测：探测无人机目标及轨迹数量≥12架次。                                    ','Multi-target detection: Detect ≥12 UAV targets and trajectories.','63168383d8591398d5f38805d79ea95d',null,null,null,'1776204893');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1263','
                                        多系统组网探测：支持与频谱、雷达等设备组网，并融合探测数据。                                    ','Multi-system network detection: Supports networking with spectrum, radar and other equipment, and integrates detection data.','d16595a6266d7b864d3e7401fb38de8b',null,null,null,'1776204893');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1264','
                                        多传输方式：支持有线网络、4G/5G等数据传输方式。                                    ','Multiple transmission methods: Supports data transmission methods such as wired network, 4G/5G, etc.','492f65e691bde5f2731bd209920d603c',null,null,null,'1776204893');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1265','
                                        多标准模式： 支持《民用无人驾驶航空器系统安全要求》(GB42590-2023)强制技术要求的无人机。支持美国ASTM F3411-22a、欧盟ASD-STAN PrEN 4709-002 标准。                                    ','Multi-standard mode: Supports UAVs that meet the mandatory technical requirements of the "Safety Requirements for Civil Unmanned Aerial Vehicle Systems" (GB42590-2023). Supports US ASTM F3411-22a and EU ASD-STAN PrEN 4709-002 standards.','b4d96b21bb36527b85c1b91d501a015e',null,null,null,'1776204893');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1266','
                                        拓展ADS-B：具备对ADS-B报文的接收解析能力，可提供周边空域态势感知监视及碰撞冲突预警。                                    ','Extended ADS-B: It has the ability to receive and parse ADS-B messages, and can provide situational awareness monitoring and collision warning for the surrounding airspace.','15009d9b92cc5706a38696e7b7224b3c',null,null,null,'1776204893');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1267','Remote ID（标准）、ADS-B（拓展）','Remote ID (standard), ADS-B (extended)','901aeca72d71ca482620bcbd1abf328e',null,null,null,'1776204893');
