INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1286','
                                        不含放射性源真空紫外光电离源，使用更安全、方便，能同时准备分析爆炸物和毒品成份；                                    ','The vacuum ultraviolet photoionization source, which does not contain radioactive sources, is safer and more convenient to use, and can simultaneously prepare and analyze explosives and drug components.','0decf0ea04441b93667105c551daadeb',null,null,null,'1776204965');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1287','
                                        黑火药纳克级检测性能，包括烟花爆竹、民用土制炸药等；                                    ','Nanogram-level testing performance of black powder, including fireworks, firecrackers, and homemade explosives;','917bdafb2a269c12a9fbf0044bc36e97',null,null,null,'1776204965');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1288','
                                        检测分析速度快，6秒以内就能出结果；                                    ','The detection and analysis speed is fast, and results can be obtained within 6 seconds;','657235134573426ec5c667b7a67a8306',null,null,null,'1776204965');
