INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1307','黑火药（Black Powder）、硝酸铵（AN）、梯恩梯（TNT）1纳克、奥克托今（HMX）、二硝基甲苯（DNT）、三硝基苯甲硝胺（Tetryl），太安（PETN）、黑索金(RDX)、六硝基芪（HNS）、硝化甘油（NG）、吉纳（NA）及各种民用和土制炸药等','Black powder, ammonium nitrate (AN), TNT (1 nanogram), octogen (HMX), dinitrotoluene (DNT), trinitrobenzenenitamine (Tetryl), PETN, RDX, hexanitrostilbene (HNS), nitroglycerin (NG), nitroglycerin (NA), and various civilian and homemade explosives, etc.','11b609cfc73864b580275c3f7cdac0cc',null,null,null,'1776204965');
