INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1317','光学识别跟踪设备_反无设备_产品中心_非传科技','Optical Recognition Tracking Equipment_Anti-Non-Electronic Devices_Product Center_Feichuan Technology','7da54bf22fc6c46aa4cd26b6ca8a3013',null,null,null,'1776204965');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1318','光学识别跟踪设备集高清可见光摄像机、制冷/非制冷热成像仪、激光照明器等多频谱探测模块、自动跟踪、智能分析和精密电子控制于一体，采用小型化隐蔽式结构设计，用于实现对小型无人机目标的探测、定位、跟踪和识别，并可与通信侦测分系统、雷达探测分系统互相引导，实现对空中小型无人机或其他低慢小目标的侦察判证和视频取证。','The optical recognition and tracking equipment integrates a high-definition visible light camera, a cooled/uncooled thermal imager, a laser illuminator, and other multi-spectral detection modules, along with automatic tracking, intelligent analysis, and precision electronic control. It adopts a miniaturized and concealed structural design to detect, locate, track, and identify small UAV targets. It can also guide the communication detection subsystem and radar detection subsystem to achieve reconnaissance, verification, and video evidence collection of small UAVs or other low-speed, small targets in the air.','bd2901879d8e88bed1983174aa2ff739',null,null,null,'1776204965');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1319','高品质设计，外壳选用超强铝合金材质，球面低风阻设计，抗强风、低扰动。采用内外双层“三防”技术和真空充氮密封技术，整机防护等级达到IP66,有效确保设备在野外恶劣环镜中长期稳定运转。','High-quality design, with a casing made of ultra-strong aluminum alloy and a spherical low-drag design, making it resistant to strong winds and low disturbance. Utilizing double-layer "three-proof" technology and vacuum nitrogen-filled sealing technology, the entire unit achieves an IP66 protection rating, effectively ensuring long-term stable operation in harsh outdoor environments.','593c2899f6c4458a0f25a04f0da85ab9',null,null,null,'1776204965');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1320','
                                        负载能力强：可承载长焦可见光摄像机、大口径热像仪、随动激光照明器，选配激光测距、定位导航、数字罗盘等传感模块，实现超远距离目标观测。                                    ','High load capacity: It can carry long-focal-length visible light cameras, large-aperture thermal imagers, and follow-up laser illuminators. With optional laser ranging, positioning and navigation, digital compass and other sensing modules, it can achieve ultra-long-distance target observation.','e0fb4ad0a0d5868cdb4bb13188f132c0',null,null,null,'1776204965');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1321','
                                        探测频谱宽：可集成高清可见光、制冷/非制冷热成像、激光照明器，多波段探测优势互补，主被动探测相结合，多源数据汇聚融合处理，满足昼夜、全天候环境下的监控需求。                                    ','Wide detection spectrum: It can integrate high-definition visible light, cooled/uncooled thermal imaging, and laser illuminators, with complementary advantages of multi-band detection, a combination of active and passive detection, and multi-source data convergence and fusion processing to meet the monitoring needs of day and night and all-weather environments.','61a74a231ac85597eb7c3ff9bd0315d5',null,null,null,'1776204965');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1322','
                                        调转速度快：回转速度可达80°/s,加速度可达100°/s，启停迅速，运转流畅，有助于捕获、跟踪快速移动目标。                                    ','Fast turning speed: The turning speed can reach 80°/s, and the acceleration can reach 100°/s. It can start and stop quickly and operate smoothly, which helps to capture and track fast-moving targets.','56996f34a0c122d2ad57bb443313cf19',null,null,null,'1776204965');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1323','
                                        覆盖范围广：方位回转范围0°~360°，俯仰回转范围-90°~+90°，实现无死角探测、全维度覆盖。                                    ','Wide coverage: azimuth rotation range of 0°~360°, pitch rotation range of -90°~+90°, achieving detection without blind spots and full-dimensional coverage.','d06da87dc167588bbfff7e73802b23e5',null,null,null,'1776204965');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1324','
                                        控制精度高：采用精密角度编码器配合高精度闭环伺服控制系统，定位精度可达0.02°，高性能图像处理单元搭配高精度聚焦控制机构，实现精确的自动聚焦。                                    ','High control precision: It adopts a precision angle encoder in combination with a high-precision closed-loop servo control system, and the positioning accuracy can reach 0.02°. The high-performance image processing unit is combined with a high-precision focusing control mechanism to achieve precise automatic focusing.','b79bf7b6120c5801353d0d3eef92da0f',null,null,null,'1776204965');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1325','
                                        跟踪性能优：多种先进的目标捕获算法和跟踪算法设计的自动跟踪模块，辅以高精度伺服控制，确保目标在快速飞行及变向过程中的稳定跟踪。                                    ','Superior tracking performance: The automatic tracking module, designed with a variety of advanced target acquisition and tracking algorithms and supplemented by high-precision servo control, ensures stable tracking of targets during rapid flight and changes of direction.','6f679230df1451bb6b403efb995b50bc',null,null,null,'1776204965');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1326','
                                        智能化程度高：支持目标入侵检测、移动侦测等异常行为检测，支持目标分类识别，支持热点告警、雷达联动、3D缩放定位等功能，大大提升了系统的无人化、自动化、信息化水平。                                    ','High level of intelligence: It supports abnormal behavior detection such as target intrusion detection and motion detection, target classification and recognition, hotspot alarm, radar linkage, 3D zoom positioning and other functions, which greatly improves the unmanned, automated and information-based level of the system.','0f24c32e63b2e121fc702f60c4a3dcf8',null,null,null,'1776204965');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1327','
                                        多重主动保护：强热源保护，内部温度监控，定向工业除霜器，提升系统的可靠性。                                    ','Multiple active protections: strong heat source protection, internal temperature monitoring, and directional industrial defrost device enhance system reliability.','0a9dd2682c087073be4e1bad7248be23',null,null,null,'1776204965');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1328','
                                        环境适应性强：高强度铝合金材料，内外双层三防技术，IP66保护。                                    ','High environmental adaptability: made of high-strength aluminum alloy, with double-layer three-proof technology inside and out, and IP66 protection.','2d96fc31bcda2d63183e80ae28d9d6bd',null,null,null,'1776204965');
