INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1392','321型钢桥面板净宽990，长3米，高105MM；','The 321 type steel bridge deck has a net width of 990 mm, a length of 3 meters, and a height of 105 mm.','75860cc1db34027710f33957fe06ee36',null,null,null,'1776204991');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1393','200型钢桥面板净宽1050，长3.048米,由于200型桥面板要求承载能力高，所以高度达到140MM，高与321型桥面板。','The 200-type steel bridge deck has a net width of 1050 mm and a length of 3.048 meters. Because the 200-type bridge deck requires high load-bearing capacity, its height reaches 140 mm, which is higher than that of the 321-type bridge deck.','e87149a5c4d202d1609df5246c26268b',null,null,null,'1776204991');
