INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1545','根据物质材质，24位真彩色显示，支持彩色/黑白、局增、高穿、低穿、超增、有机物剔除、无机物剔除、反色、加亮、减暗、灰扫、放大、伪彩、有机物增强、可疑物品报警标记、边缘增强处理','Based on the material composition, it features 24-bit true color display, supporting color/black and white, partial enhancement, high penetration, low penetration, super enhancement, organic matter removal, inorganic matter removal, color inversion, brightening, darkening, gray sweep, magnification, false color, organic matter enhancement, suspicious item alarm marking, and edge enhancement processing.','c8d5b0ec6357b55759c897b48a475775',null,null,null,'1776205070');
