INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1566','手持式无线电侦测设备_反无设备_产品中心_非传科技','Handheld Radio Detection Equipment_Anti-Noise Equipment_Product Center_Feichuan Technology','b90d7545ff0c658e7606dd87b51be398',null,null,null,'1776205074');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1567','无线电侦测设备能够探测发现400MHz、800MHz、900MHz、1.2GHz、1.4GHz、2.4GHz、5.2GHz、5.8GHz频谱范围内无人机的无线电信号，监测范围为半径2km。设备在开启后，可迅速自动对其进行探测、发现，通过声光报警对无人机的探测结果进行预警。','The radio detection equipment can detect the radio signals of drones in the spectrum ranges of 400MHz, 800MHz, 900MHz, 1.2GHz, 1.4GHz, 2.4GHz, 5.2GHz, and 5.8GHz, with a monitoring range of 2km radius. Once activated, the equipment can quickly and automatically detect and identify drones, providing early warnings through audible and visual alarms.','5b9ac5443b0f0c2f78a2b0f5d66f9294',null,null,null,'1776205074');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1568','
                                        无源检测：只被动接收不发射任何电磁信号，对环境无影响。                                    ','Passive detection: It only passively receives signals and does not emit any electromagnetic signals, so it has no impact on the environment.','a346203aa69671c3680b878777e2ba68',null,null,null,'1776205074');
