INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1591','设备通过无线电频率扫描无人机频谱特征，解析Drone ID和Remote ID报文，侦测非法入侵的无人机，能够识别无人机与遥控器之间的控制信号、图传信号；并通过电磁压制技术，实现对无人机遥控链路、图传链路和导航信号的干扰阻断，迫使无人机返航或降落。','The device scans the spectrum characteristics of drones via radio frequencies, analyzes Drone ID and Remote ID messages, detects illegally intruding drones, and can identify control signals and image transmission signals between the drone and the remote controller. It also uses electromagnetic suppression technology to interfere with and block the drone\'s remote control link, image transmission link, and navigation signals, forcing the drone to return or land.','145f2e9dc9c70763505d08c7184d5375',null,null,null,'1776205074');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1592','
                                        打击距离远：空旷环境下可达2km（典型目标：御2）                                    ','Long strike range: up to 2km in open environments (typical target: Mavic 2)','457738fbf89984dc06ec3ba4919ad2c1',null,null,null,'1776205074');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1593','
