INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1714','1. 智能分析：支持区域入侵检测、越界入侵检测、移动侦测、巡航检测以及徘徊检测、聚集检测、滞留检测、逆行检测等
2. 自动跟踪：支持多场景跟踪、报警联动跟踪','1. Intelligent Analysis: Supports area intrusion detection, boundary crossing detection, motion detection, patrol detection, as well as loitering detection, gathering detection, lingering detection, and reverse movement detection. 2. Automatic Tracking: Supports multi-scenario tracking and alarm-linked tracking.','6690e2f07cb6ef7abd4c34bff18dc4a7',null,null,null,'1776205125');
