INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1751','手提式无线电侦测设备具有300MHz ~ 6000MHz全频段探测能力，可实现对探测范围内无人机的侦测、识别、定位、跟踪、声光报警等功能。设备在开启后，可自动进入工作状态。设备具有便携性、机动性、快速部署等特点。','This handheld radio detection device has a full-band detection capability of 300MHz to 6000MHz, enabling it to detect, identify, locate, track, and trigger audible and visual alarms for drones within its detection range. The device automatically enters operational mode after being powered on. It features portability, mobility, and rapid deployment.','e63b52688134e755f0eb1bc46a59fddd',null,null,null,'1776205253');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1752','
                                        无源检测：只被动接收不发射任何电磁信号对环境无影响。                                    ','Passive detection: It only passively receives signals and does not emit any electromagnetic signals, so it has no impact on the environment.','105c380da98bd59360384b436492b572',null,null,null,'1776205253');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1753','
                                        多模式识别：支持频谱识别、报文解析识别。                                    ','Multi-mode recognition: Supports spectrum recognition and message parsing recognition.','e8048e3239608af0452fa679abd8a415',null,null,null,'1776205253');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1754','
                                        精准识别：可精准识别主流品牌无人机的序列号、型号、位置、速度、高度、航迹及遥控器（飞手）位置信息。                                    ','Accurate identification: It can accurately identify the serial number, model, location, speed, altitude, flight path, and remote controller (pilot) location information of mainstream brand drones.','91dce6c8822f72f32112685de3b1a65e',null,null,null,'1776205253');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1755','
                                        黑白名单：可一键标记黑白名单白名单无人机不报警侦测识别机型多，支持市场主流品牌、WiFi机及DIY无人机。                                    ','Blacklist/Whitelist: Allows for one-click blacklisting and whitelisting. Whitelisted drones do not trigger alarms. Detection and identification supports a wide range of models, including mainstream brands, WiFi drones, and DIY drones.','f5611bfc18b87096bf4148527cc94e15',null,null,null,'1776205253');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1756','
                                        目标定位：可精准定位主流品牌无人机/遥控器（飞手）位置。                                    ','Target positioning: It can accurately locate the position of mainstream brand drones/remote controllers (pilots).','b64d76d1fa50da810e7c1dd94cd52e14',null,null,null,'1776205253');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1757','
                                        全频段探测：对300MHz~6000MHz全频段探测。                                    ','Full-band detection: Detects the entire frequency band from 300MHz to 6000MHz.','a71099613bb701601877434a1e7c95c8',null,null,null,'1776205253');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1758','
                                        联网上报：支持联网接入后端指挥平台。                                    ','Network reporting: Supports network access to the backend command platform.','c1138dd639af6fcf315c864d1e1c7ca4',null,null,null,'1776205253');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1759','
                                        轨迹跟踪：具备多目标轨迹跟踪功能同时探测到多台无人机时能够以不同颜色显示其飞行轨迹。                                    ','Trajectory tracking: It has multi-target trajectory tracking function and can display the flight trajectories of multiple drones in different colors when multiple drones are detected at the same time.','1391139d9b4d10bc177895bada2e207c',null,null,null,'1776205253');
