INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1790','桥台等条件具备后3-7个晴天日（根据桥梁长度和现场条件确定）','After the bridge abutments and other conditions are met, 3-7 sunny days are required (depending on the bridge length and site conditions).','46276aeee860b696ee9d55508a426754',null,null,null,'1776205253');
