INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1804','3.15米特制单车道； 4.2米标准单车道； 7.35米标准双车道；（也可根据客户需求特制）','3.15-meter custom-made single lane; 4.2-meter standard single lane; 7.35-meter standard double lane; (custom designs are also available upon request)','108a0a4ef23f94cdaeaa6882cb985bf3',null,null,null,'1776205301');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1805','单车道60.96米单跨；双车道45.72米单跨；（若总长大于最大单跨长度，可做多跨连续梁，也可选择GWD型钢桥）','A single-lane bridge has a 60.96-meter single span; a double-lane bridge has a 45.72-meter single span; (If the total length exceeds the maximum single span length, a multi-span continuous beam can be constructed, or a GWD-type steel bridge can be selected)','9eabe0b24cb2532ffa86c83f8fa5bcdf',null,null,null,'1776205301');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1806','汽车10级；汽车15级；汽车20级；履带-50级；挂车-80级；单车40吨；单车60吨；单车150吨；AASHTO HS20，HS25-44，HL93，BS5400 HA + HB；域-A；域-B；公路-I级；公路-II级；印度标准Class-40；澳大利亚标准T44；韩国标准D24 等。','Vehicle Class 10; Vehicle Class 15; Vehicle Class 20; Tracked Class 50; Trailer Class 80; Single Vehicle 40 Tons; Single Vehicle 60 Tons; Single Vehicle 150 Tons; AASHTO HS20, HS25-44, HL93, BS5400 HA + HB; Domain-A; Domain-B; Highway Class I; Highway Class II; Indian Standard Class-40; Australian Standard T44; Korean Standard D24, etc.','5b8174d5874cddb7965caa6f3653d810',null,null,null,'1776205301');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1807','热镀锌；油漆；钢结构重型防腐油漆；沥青漆；桥面板防滑骨料处理等。','Hot-dip galvanizing; painting; heavy-duty anti-corrosion paint for steel structures; asphalt paint; anti-slip aggregate treatment for bridge decks, etc.','1d0ce89ada2dd99b893d32bb6697f45a',null,null,null,'1776205301');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1808','悬臂推出法；吊装法；浮运法；就地拼装法；堆土施工法等。','Cantilever launching method; hoisting method; floating method; on-site assembly method; earthwork construction method, etc.','0bf4452cc65b592e94eef941b9fdcda3',null,null,null,'1776205301');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1809','吊车，卷扬机，千斤顶，手拉葫芦等。（可根据现场条件调整）','Cranes, winches, jacks, chain hoists, etc. (Adjustments can be made according to site conditions)','2905a5f0dc935deeeeb8082bd224231f',null,null,null,'1776205301');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1810','交货期短，配件轻便，装配快速，可互换，可拆卸，寿命长；承载能力大，寿命长。','Short delivery time, lightweight parts, quick assembly, interchangeable, detachable, long service life; high load-bearing capacity, long service life.','3a9159b54d58ef37c2ebb5d697ea3fcc',null,null,null,'1776205301');
