INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1812','无线电干扰设备（全向）_反无设备_产品中心_非传科技','Radio jamming equipment (omnidirectional) - Anti-jamming equipment - Product Center - Feichuan Technology','89c7f1be1ba5487db781309e7a8b6bb1',null,null,null,'1776205375');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1813','全向无线电干扰设备通过发射不同频率的电子干扰信号，对无人机的控制链路、导航链路和图传链路进行压制式干扰，从而迫使无人机自动降落或将其驱离，保障低空空域安全，是大型活动和重要场所的安全卫士。','Omnidirectional radio jamming equipment suppresses the control, navigation, and image transmission links of drones by emitting electronic jamming signals at different frequencies, thereby forcing drones to land automatically or driving them away, ensuring the safety of low-altitude airspace, and serving as a security guardian for large-scale events and important venues.','57ed7742b8bfa0bae0f2b6801595c9df',null,null,null,'1776205375');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1814','
                                        导航干扰全：处置频率范围包含GPS、GLONASS、北斗、伽利略等不同类型导航系统。                                    ','Comprehensive navigation interference handling: The frequency range it handles includes different types of navigation systems such as GPS, GLONASS, BeiDou, and Galileo.','6e9d380d99c3fb1d2922341e2879c5cc',null,null,null,'1776205375');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1815','
                                        干扰频段可选：能单独、组合、同时发射各频段的干扰信号。                                    ','The interference frequency bands are selectable: it can transmit interference signals of various frequency bands individually, in combination, or simultaneously.','f5665bf6913cf805d8fdadf966542310',null,null,null,'1776205375');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1816','
                                        全向干扰：以全向的方式发射干扰信号，360°全向防御。                                    ','Omnidirectional jamming: Transmits jamming signals in an omnidirectional manner, providing 360° omnidirectional defense.','8db27c6e5f2b6e46b1404c61ff83f372',null,null,null,'1776205375');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1817','400MHZ、800MHZ、900MHZ、1.2GHZ、1.4GHZ、1.5GHz、2.4GHz、5.8GHZ、5.1GHz~5.9GHz','400MHZ、800MHZ、900MHZ、1.2GHZ、1.4GHZ、1.5GHz、2.4GHz、5.8GHZ、5.1GHz~5.9GHz','ffe92cd43282b117b56f05e3d0975aaf',null,null,null,'1776205375');
