INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1857','FC-RC系列高清激光摄像机_要地防护_产品中心_非传科技','FC-RC Series High-Definition Laser Cameras - Key Site Protection - Product Center - Feichuan Technology','ebd64b514eb8bf035fb8846fe7c73842',null,null,null,'1776205834');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1858','FC-RC系列高清激光摄像机采用超匀化激光作照明源，使用低照度长焦摄像机，集成高清可见光成像技术与超匀化激光照明技术，具有部署灵活、智能化程度高、环境适应性强等特点，可应用于各种领域的远距离昼夜连续监控。','The FC-RC series high-definition laser cameras use ultra-uniform lasers as illumination sources and employ low-light long-focal-length cameras. They integrate high-definition visible light imaging technology with ultra-uniform laser illumination technology, featuring flexible deployment, high intelligence, and strong environmental adaptability. They can be applied to long-distance day and night continuous monitoring in various fields.','be29f91373ec6d275ca3a415becc7c0a',null,null,null,'1776205834');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1859','
                                        数字化步进随动变角激光照明技术                                    ','Digital step-following variable angle laser illumination technology','17a52c244a8eb8f5deb1012d77144968',null,null,null,'1776205834');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1860','
                                        超匀化高清激光照明技术，高精度光轴自锁对准                                    ','Ultra-uniform high-definition laser illumination technology, high-precision optical axis self-locking alignment','fbbff785eb58b6baac1d828fbe358818',null,null,null,'1776205834');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1861','
                                        独立光敏控制，摄像机的彩转黑与激光开关精确同步                                    ','Independent photosensitive control ensures precise synchronization between the camera\'s color-to-black and laser switch transitions.','e18f742465ea3c997e1c6b075519ad01',null,null,null,'1776205834');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1862','
                                        支持越界/入侵检测、联动报警等智能化功能                                    ','Supports intelligent functions such as boundary crossing/intrusion detection and alarm linkage.','eba3899a0c45e8e8685a79986582e590',null,null,null,'1776205834');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1863','
                                            1. 传感器：背照式超低照度星光级CMOS
2. 分辨率：1920×1080
3. 照度：彩色:0.0005Lux；黑白：0.0001Lux；0Lux（IRON）
4. 镜头焦距：11mm～860
