INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1874','FC-DTVC系列双波段热成像高速球_要地防护_产品中心_非传科技','FC-DTVC Series Dual-Band Thermal Imaging High-Speed ​​Dome - Key Site Protection - Product Center - Feichuan Technology','8c0700f3de2e406b86d072b8c4b6da2a',null,null,null,'1776205877');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1875','FC-DTVC系列双波段热成像高速球是为特种应用场合设计的光学产品。产品整体采用高速球设计理念，结构简单可靠、紧凑精巧；定位精度高转速快，启停平稳，控制方便。集成高清可见光、激光照明模块、动力机构、精密传动装置、数字解码器、图像处理模块和控制模块等，适用于全天候昼夜24小时的图像采集及监控。','The FC-DTVC series dual-band thermal imaging high-speed dome is an optical product designed for specialized applications. The product adopts a high-speed dome design concept, featuring a simple, reliable, compact, and sophisticated structure; high positioning accuracy, fast rotation speed, smooth start-up and shutdown, and convenient control. It integrates high-definition visible light and laser illumination modules, a power mechanism, a precision transmission device, a digital decoder, an image processing module, and a control module, making it suitable for 24/7 image acquisition and monitoring in all weather conditions.','69f22a7db354029618d0cb1da2f44a57',null,null,null,'1776205877');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1876','
                                        多维感知：支持图像标尺；支持接入多种传感器。                                    ','Multi-dimensional perception: Supports image scales; supports connection to multiple sensors.','984e1809bbf08546f6fc5c3798edcfa1',null,null,null,'1776205877');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1877','
                                        高清可见光、视频编码、云台护罩、控制电子系统于一体，模块化设计、集成度高，易于安装维护。                                    ','It integrates high-definition visible light, video encoding, pan-tilt housing, and control electronics system, featuring a modular design, high integration, and easy installation and maintenance.','f1de35d237ccedaf9df2dc8eded9ca0f',null,null,null,'1776205877');
INSERT INTO `dr_app_synlang_trans_en` (`id`, `word`, `trans`, `md5`, `field`, `mid`, `cid`, `inputtime`) VALUES ('1878','
                                        内置GPU芯片，支持区域入侵、进入/离开区域检测、人员聚集检测、徘徊检测、物品遗留、物品拿取等多种检测算法。                                    ','It has a built-in GPU chip and supports a variety of detection algorithms, including area intrusion detection, entry/exit area detection, people gathering detection, loitering detection, item leaving behind, and item taking.','e11c800a920d76069456ca1b252bb4b4',null,null,null,'1776205877');
