INSERT INTO `dr_site` (`id`, `name`, `domain`, `setting`, `disabled`, `displayorder`) VALUES ('1','无人与反无人装备 - 北京非传装备科技有限公司','www.n-tetbj.com','{"config":{"logo":"/images/logo.png","SITE_NAME":"无人与反无人装备 - 北京非传装备科技有限公司","SITE_ICP":"京ICP备19040008号","SITE_TONGJI":"","flogo":"/images/logoac.png","email":"info@n-tetbj.com","tel":"010-83622127","address":"北京市丰台区丽泽路聚杰金融大厦","right":"版权所有@北京非传装备科技有限公司","ewm":"156","hdtp":{"1":{"1":"0","2":"157","3":"https://videos.feeyr.com/sv/1d3bd1c6-19d89935fcb/1d3bd1c6-19d89935fcb.mp4","4":"全球无人安防领域<br> 防御专家","5":""}},"index_3_subtitle":"创新产品<br>共建安全的世界","index_3_desc":"为全球客户提供<br>全场景一体化安全解决方案","index_4":{"1":{"1":"关键设施防护","2":"针对发电站、政府机构、铁路设施、机场等关键设施防护，构建反无人机立体安防系统，通过建立低空空域管控一体化平台。","3":"/images/isimg1.jpg","4":"./index.php?c=show&id=37"},"2":{"1":"要地安保","2":"重要场所涵盖国家设施、军事要地、政府办公场所等。重要场所应率先采用多传感器融合、人工智能、物联网等前沿技术，实现安防的精细化、智能化管理，大幅增强安全性。","3":"/images/isimg2.jpg","4":"./index.php?c=show&id=38"},"3":{"1":"边境巡逻","2":"根据边境防护的大防区无人机管控需求，采用分布式多节点组合布控方式、全系统设备部署方案，提供具有远距离发现功能的雷达、无线电、光电设备。","3":"/images/isimg3.jpg","4":"./index.php?c=show&id=39"},"4":{"1":"应急响应","2":"针对断网断电等极端场景，提供集高空通信中继、光电侦查搜救与大功率系留照明于一体的无人机矩阵，快速打通救援生命线，保障全天候的应急协同与指挥。","3":"/images/isimg4.jpg","4":"./index.php?c=show&id=40"}},"index_3_bt":{"1":{"1":"专注于无人与反无人系统领域<br>的国家级高新技术企业","2":"北京非传装备科技有限公司坐落于北京丽泽商务区，是一家专注于无人与反无人系统领域的国家级高新技术企业。公司立足国内、辐射全球，以统筹海内外优质资源与市场为核心抓手，构建非传统领域高效协同的产业桥梁，矢志打造具有国际竞争力的一流跨国科技企业。我们秉持“连接技术与应用、融通国内与国际”的发展使命，为全球客户提供顶尖一体化安全保障服务。","3":"/images/iaimg1.png"}},"index_2":"时刻与您分享<br>了解非传精彩动态","about_1_title":"致力于成为<br>全球低空安防领域领航者","about_1":"<div class=\\"desc wow fadeInUp\\">\\r\\n                <p>\\r\\n                    北京非传装备科技有限公司坐落于北京丽泽商务区，是一家专注于无人与反无人系统领域的国家级高新技术企业。公司立足国内、辐射全球，以统筹海内外优质资源与市场为核心抓手，构建非传统领域高效协同的产业桥梁，矢志打造具有国际竞争力的一流跨国科技企业。我们秉持“连接技术与应用、融通国内与国际”的发展使命，为全球客户提供顶尖一体化安全保障服务。\\r\\n                </p>\\r\\n                <p>\\r\\n                    公司核心业务以无人与反无人技术为核心支柱，提供全场景一体化安全解决方案，广泛覆盖智慧警务、工程补给、野战医疗、要地防护等多元实用场景。依托自主研发的先进无人平台侦察监测技术与高效精准的反无人防御拦截技术，深度聚焦关键基础设施防护、要地安保、边境巡逻、应急响应等核心领域，为客户量身定制高效可靠的解决方案，凭借扎实技术优势与丰富实战经验，精准化解低空、超低空领域的现实及潜在安全威胁，为守护人民生命财产安全筑牢技术屏障。\\r\\n                </p>\\r\\n            </div>\\r\\n            <div class=\\"name wow fadeInUp\\">构建“侦察-识别-拦截-处置”全链路自主技术体系</div>\\r\\n            <div class=\\"desc wow fadeInUp\\">\\r\\n                <p>核心研发团队由10+行业资深专家领衔，平均从业经验15年以上，兼具深厚技术积淀与成熟民用场景落地能力，全流程响应周期较行业平均缩短30%，实现技术与场景精准适配。</p>\\r\\n            </div>","menu7_10_title":{"1":{"1":"企业愿景","2":"跻身无人安防领域全球领军行列，以持续技术创新\\r\\n                    驱动安全防护升级，为国家安全、社会稳定<br>及全球安全治理贡献卓越力量","3":"秉持“团结协作、求实创新、合作共赢”的企业精神，<br>\\r\\n            北京非传装备科技有限公司诚邀各界伙伴携手，共克新时代多元安全挑战，共筑和平繁荣的美好未来！"}},"about_1_video":{"1":{"1":"全球服务","2":"作为“一带一路”倡议深度践行者，非传装备具备卓越的政策研判与全球资源整合能力。依托全球化视野与成熟跨国合作经验，联动海内外50+产业链核心资源，严守国际标准推进研发交付，为全球客户提供技术先进、场景适配、安全可靠的优质产品与服务。","3":"/images/acimg1.png"}},"menu6_7":{"1":{"1":"联动海内外50+产业链核心资源","2":"50","3":"+"}},"menu6_8":"荣誉资质","about_3":{"id":["21","22","23"],"file":["202603/0dceb845cee3973.jpg","202603/cdb51293ed10696.jpg","202603/0ce7b13ff05493c.jpg"],"description":["中国安防报警服务类十大影响力品牌","武器装备管理体系认证证书","国家应急产业重点联系企业"]},"jobs_1_title":{"1":{"1":"以人为本<br>人才是企业发展的重要资源","2":"<p>我们秉持 “知行合一，通达四海” 的核心人才理念，广纳天下贤才。既看重人才扎实的专业学识与卓越的创新思维，更注重理论落地、躬身践行的实干能力，拒绝空谈，崇尚用行动创造价值。</p>\\r\\n                <p><br></p>\\r\\n                <p>\\r\\n                    我们为人才搭建多元发展平台，提供广阔的成长空间与公平的晋升通道。助力每一位实干者深耕专业、突破自我，将个人理想与企业发展紧密相连。鼓励人才勇闯市场、开拓疆域，以过硬的本领行稳致远，携手共赴广阔前程，成就彼此，共赢未来。\\r\\n                </p>"}},"job_2":{"1":{"1":"/images/jaicon2.png","2":"以积极合理的制度激励人才"},"2":{"1":"/images/jaicon3.png","2":"以科学有效的学习培养人才"},"3":{"1":"/images/jaicon4.png","2":"以真挚高尚的情感留住人才"}},"jobs_3":{"1":{"1":"在这里，工作与美好相伴。我们用心营造有温度的企业环境，让每一份努力都被善待，让员工的成长之路满是舒心与归属感。","2":"<dl class=\\"wow fadeInUp\\">\\r\\n                    <dt>01</dt>\\r\\n                    <dd>舒适放松的工作氛围</dd>\\r\\n                </dl>\\r\\n                <dl class=\\"wow fadeInUp\\">\\r\\n                    <dt>02</dt>\\r\\n                    <dd>宽敞舒适的办公空间</dd>\\r\\n                </dl>\\r\\n                <dl class=\\"wow fadeInUp\\">\\r\\n                    <dt>03</dt>\\r\\n                    <dd>融洽和睦的同事关系</dd>\\r\\n                </dl>"}},"jobs_1_img":{"id":["/images/jbimg1.jpg","/images/jbimg2.jpg","/images/jbimg3.jpg"],"file":["/images/jbimg1.jpg","/images/jbimg2.jpg","/images/jbimg3.jpg"]},"jobs_email":"我们真诚邀请世界各地的优秀人才加入我们的团队，如果您对我们的招聘岗位感兴趣，欢迎投递简历到：<a href=\\"mailto:info@n-tetbj.com\\">info@n-tetbj.com</a>","SITE_CLOSE":"0","SITE_INDEX_HTML":"0","SITE_CLOSE_MSG":"网站升级中....","SITE_LANGUAGE":"zh-cn","SITE_TEMPLATE":"small","SITE_TIMEZONE":"8","SITE_TIME_FORMAT":"","SITE_THEME":"default"},"param":{"flogo":"/images/logoac.png","tel":"010-83622127","address":"北京市丰台区丽泽路聚杰金融大厦","about_1":"&lt;div class=&quot;desc wow fadeInUp&quot;&gt;\\r\\n                &lt;p&gt;\\r\\n                    北京非传装备科技有限公司坐落于北京丽泽商务区，是一家专注于无人与反无人系统领域的国家级高新技术企业。公司立足国内、辐射全球，以统筹海内外优质资源与市场为核心抓手，构建非传统领域高效协同的产业桥梁，矢志打造具有国际竞争力的一流跨国科技企业。我们秉持“连接技术与应用、融通国内与国际”的发展使命，为全球客户提供顶尖一体化安全保障服务。\\r\\n                &lt;/p&gt;\\r\\n                &lt;p&gt;\\r\\n                    公司核心业务以无人与反无人技术为核心支柱，提供全场景一体化安全解决方案，广泛覆盖智慧警务、工程补给、野战医疗、要地防护等多元实用场景。依托自主研发的先进无人平台侦察监测技术与高效精准的反无人防御拦截技术，深度聚焦关键基础设施防护、要地安保、边境巡逻、应急响应等核心领域，为客户量身定制高效可靠的解决方案，凭借扎实技术优势与丰富实战经验，精准化解低空、超低空领域的现实及潜在安全威胁，为守护人民生命财产安全筑牢技术屏障。\\r\\n                &lt;/p&gt;\\r\\n            &lt;/div&gt;\\r\\n            &lt;div class=&quot;name wow fadeInUp&quot;&gt;构建“侦察-识别-拦截-处置”全链路自主技术体系&lt;/div&gt;\\r\\n            &lt;div class=&quot;desc wow fadeInUp&quot;&gt;\\r\\n                &lt;p&gt;核心研发团队由10+行业资深专家领衔，平均从业经验15年以上，兼具深厚技术积淀与成熟民用场景落地能力，全流程响应周期较行业平均缩短30%，实现技术与场景精准适配。&lt;/p&gt;\\r\\n            &lt;/div&gt;","about_3":"{\\"file\\":[\\"21\\",\\"22\\",\\"23\\"],\\"title\\":[\\"\\",\\"\\",\\"\\"],\\"description\\":[\\"中国安防报警服务类十大影响力品牌\\",\\"武器装备管理体系认证证书\\",\\"国家应急产业重点联系企业\\"]}","hdtp":"{\\"1\\":{\\"1\\":\\"0\\",\\"2\\":\\"157\\",\\"3\\":\\"https://videos.feeyr.com/sv/1d3bd1c6-19d89935fcb/1d3bd1c6-19d89935fcb.mp4\\",\\"4\\":\\"全球无人安防领域<br> 防御专家\\",\\"5\\":\\"\\"}}","index_2":"时刻与您分享&lt;br&gt;了解非传精彩动态","index_3_bt":"{\\"1\\":{\\"1\\":\\"专注于无人与反无人系统领域<br>的国家级高新技术企业\\",\\"2\\":\\"北京非传装备科技有限公司坐落于北京丽泽商务区，是一家专注于无人与反无人系统领域的国家级高新技术企业。公司立足国内、辐射全球，以统筹海内外优质资源与市场为核心抓手，构建非传统领域高效协同的产业桥梁，矢志打造具有国际竞争力的一流跨国科技企业。我们秉持“连接技术与应用、融通国内与国际”的发展使命，为全球客户提供顶尖一体化安全保障服务。\\",\\"3\\":\\"/images/iaimg1.png\\"}}","index_3_desc":"为全球客户提供&lt;br&gt;全场景一体化安全解决方案","index_4":"{\\"1\\":{\\"1\\":\\"关键设施防护\\",\\"2\\":\\"针对发电站、政府机构、铁路设施、机场等关键设施防护，构建反无人机立体安防系统，通过建立低空空域管控一体化平台。\\",\\"3\\":\\"/images/isimg1.jpg\\",\\"4\\":\\"./index.php?c=show&id=37\\"},\\"2\\":{\\"1\\":\\"要地安保\\",\\"2\\":\\"重要场所涵盖国家设施、军事要地、政府办公场所等。重要场所应率先采用多传感器融合、人工智能、物联网等前沿技术，实现安防的精细化、智能化管理，大幅增强安全性。\\",\\"3\\":\\"/images/isimg2.jpg\\",\\"4\\":\\"./index.php?c=show&id=38\\"},\\"3\\":{\\"1\\":\\"边境巡逻\\",\\"2\\":\\"根据边境防护的大防区无人机管控需求，采用分布式多节点组合布控方式、全系统设备部署方案，提供具有远距离发现功能的雷达、无线电、光电设备。\\",\\"3\\":\\"/images/isimg3.jpg\\",\\"4\\":\\"./index.php?c=show&id=39\\"},\\"4\\":{\\"1\\":\\"应急响应\\",\\"2\\":\\"针对断网断电等极端场景，提供集高空通信中继、光电侦查搜救与大功率系留照明于一体的无人机矩阵，快速打通救援生命线，保障全天候的应急协同与指挥。\\",\\"3\\":\\"/images/isimg4.jpg\\",\\"4\\":\\"./index.php?c=show&id=40\\"}}","jobs_1_title":"{\\"1\\":{\\"1\\":\\"以人为本<br>人才是企业发展的重要资源\\",\\"2\\":\\"<p>我们秉持 “知行合一，通达四海” 的核心人才理念，广纳天下贤才。既看重人才扎实的专业学识与卓越的创新思维，更注重理论落地、躬身践行的实干能力，拒绝空谈，崇尚用行动创造价值。</p>\\\\r\\\\n                <p><br></p>\\\\r\\\\n                <p>\\\\r\\\\n                    我们为人才搭建多元发展平台，提供广阔的成长空间与公平的晋升通道。助力每一位实干者深耕专业、突破自我，将个人理想与企业发展紧密相连。鼓励人才勇闯市场、开拓疆域，以过硬的本领行稳致远，携手共赴广阔前程，成就彼此，共赢未来。\\\\r\\\\n                </p>\\"}}","job_2":"{\\"1\\":{\\"1\\":\\"/images/jaicon2.png\\",\\"2\\":\\"以积极合理的制度激励人才\\"},\\"2\\":{\\"1\\":\\"/images/jaicon3.png\\",\\"2\\":\\"以科学有效的学习培养人才\\"},\\"3\\":{\\"1\\":\\"/images/jaicon4.png\\",\\"2\\":\\"以真挚高尚的情感留住人才\\"}}","jobs_1_img":"{\\"file\\":[\\"/images/jbimg1.jpg\\",\\"/images/jbimg2.jpg\\",\\"/images/jbimg3.jpg\\"],\\"title\\":[\\"\\",\\"\\",\\"\\"],\\"description\\":[\\"\\",\\"\\",\\"\\"]}","jobs_3":"{\\"1\\":{\\"1\\":\\"在这里，工作与美好相伴。我们用心营造有温度的企业环境，让每一份努力都被善待，让员工的成长之路满是舒心与归属感。\\",\\"2\\":\\"<dl class=\\\\\\"wow fadeInUp\\\\\\">\\\\r\\\\n                    <dt>01</dt>\\\\r\\\\n                    <dd>舒适放松的工作氛围</dd>\\\\r\\\\n                </dl>\\\\r\\\\n                <dl class=\\\\\\"wow fadeInUp\\\\\\">\\\\r\\\\n                    <dt>02</dt>\\\\r\\\\n                    <dd>宽敞舒适的办公空间</dd>\\\\r\\\\n                </dl>\\\\r\\\\n                <dl class=\\\\\\"wow fadeInUp\\\\\\">\\\\r\\\\n                    <dt>03</dt>\\\\r\\\\n                    <dd>融洽和睦的同事关系</dd>\\\\r\\\\n                </dl>\\"}}","jobs_email":"我们真诚邀请世界各地的优秀人才加入我们的团队，如果您对我们的招聘岗位感兴趣，欢迎投递简历到：&lt;a href=&quot;mailto:info@n-tetbj.com&quot;&gt;info@n-tetbj.com&lt;/a&gt;","about_1_title":"致力于成为&lt;br&gt;全球低空安防领域领航者","about_1_video":"{\\"1\\":{\\"1\\":\\"全球服务\\",\\"2\\":\\"作为“一带一路”倡议深度践行者，非传装备具备卓越的政策研判与全球资源整合能力。依托全球化视野与成熟跨国合作经验，联动海内外50+产业链核心资源，严守国际标准推进研发交付，为全球客户提供技术先进、场景适配、安全可靠的优质产品与服务。\\",\\"3\\":\\"/images/acimg1.png\\"}}","menu6_7":"{\\"1\\":{\\"1\\":\\"联动海内外50+产业链核心资源\\",\\"2\\":\\"50\\",\\"3\\":\\"+\\"}}","menu6_8":"荣誉资质","email":"info@n-tetbj.com","menu7_10_title":"{\\"1\\":{\\"1\\":\\"企业愿景\\",\\"2\\":\\"跻身无人安防领域全球领军行列，以持续技术创新\\\\r\\\\n                    驱动安全防护升级，为国家安全、社会稳定<br>及全球安全治理贡献卓越力量\\",\\"3\\":\\"秉持“团结协作、求实创新、合作共赢”的企业精神，<br>\\\\r\\\\n            北京非传装备科技有限公司诚邀各界伙伴携手，共克新时代多元安全挑战，共筑和平繁荣的美好未来！\\"}}","index_3_subtitle":"创新产品&lt;br&gt;共建安全的世界","right":"版权所有@北京非传装备科技有限公司","ewm":"156"},"webpath":null,"client":[{"name":"en","domain":"www.n-tetbj.com/en"}]}','0','0');

